/* Clinical questions tied to each lesson ("module-lessonIndex").
   Row: [difficulty, correctIndex, qEn, qEs, optionsEn, optionsEs|0, whyEn, whyEs] */
NX.addLessonQ({
  'fund-0': [
    [2, 1, 'After handoff you have four patients. Whom do you see first?', 'Tras el relevo tienes cuatro pacientes. ¿A quién ves primero?', ['Post-op day 2 asking for pain medication (4/10)', 'COPD patient with new confusion and SpO2 85%', 'Diabetic patient asking about lunch', 'Patient waiting for discharge papers'], ['Posoperatorio día 2 que pide analgesia (4/10)', 'Paciente con EPOC con confusión nueva y SpO2 85%', 'Diabético que pregunta por la comida', 'Paciente que espera el alta'], 'A new acute change in breathing and consciousness comes first (ABC).', 'Un cambio agudo en respiración y conciencia va primero (ABC).'],
    [1, 3, 'A patient reports a new symptom. What is the first step of the nursing process?', 'Un paciente refiere un síntoma nuevo. ¿Cuál es el primer paso del proceso de enfermería?', ['Plan care', 'Implement', 'Evaluate', 'Assess'], ['Planificar', 'Ejecutar', 'Evaluar', 'Valorar'], 'Assessment always comes first.', 'La valoración siempre va primero.'],
    [2, 0, 'Which task can you delegate to a trained assistant?', '¿Qué tarea puedes delegar en un auxiliar capacitado?', ['Helping a stable patient wash and dress', 'Teaching insulin injection', 'Assessing a new admission', 'Evaluating the response to morphine'], ['Ayudar a un paciente estable a asearse y vestirse', 'Enseñar la inyección de insulina', 'Valorar un ingreso nuevo', 'Evaluar la respuesta a la morfina'], 'Routine care of a stable patient can be delegated; assessment, teaching and evaluation stay with the RN.', 'El cuidado rutinario de un paciente estable se delega; valoración, educación y evaluación son de la enfermera.']
  ],
  'fund-1': [
    [1, 2, 'Which adult vital sign needs action?', '¿Qué signo vital del adulto requiere actuar?', ['HR 88/min', 'RR 16/min', 'RR 28/min', 'Temperature 36.9 °C'], ['FC 88/min', 'FR 16/min', 'FR 28/min', 'Temperatura 36,9 °C'], 'Normal adult RR is 12-20; 28 is tachypnea.', 'La FR normal del adulto es 12-20; 28 es taquipnea.'],
    [2, 0, 'BP reads 168/94, measured with a small cuff on a large arm. Next step?', 'La PA es 168/94, medida con un manguito pequeño en un brazo grande. ¿Siguiente paso?', ['Re-measure with the correct cuff size', 'Give an antihypertensive', 'Record it as hypertension', 'Measure on the leg'], ['Repetir con el manguito adecuado', 'Dar un antihipertensivo', 'Registrar hipertensión', 'Medir en la pierna'], 'A cuff that is too small gives a falsely high reading.', 'Un manguito pequeño da una lectura falsamente alta.'],
    [2, 3, 'A patient who cannot speak after a stroke is grimacing and restless. Best pain assessment?', 'Un paciente que no puede hablar tras un ictus hace muecas y está inquieto. ¿Mejor valoración del dolor?', ['Numeric 0-10 scale', 'Ask the family to rate it', 'Wait until he can speak', 'A behavioral pain scale'], ['Escala numérica 0-10', 'Que la familia lo puntúe', 'Esperar a que hable', 'Una escala conductual del dolor'], 'Use behavioral scales for patients who cannot self-report (circular 155/2019).', 'Usa escalas conductuales si no puede autoevaluarse (circular 155/2019).']
  ],
  'fund-2': [
    [1, 1, 'A patient has suspected measles. Which precautions?', 'Paciente con sospecha de sarampión. ¿Qué precauciones?', ['Contact', 'Airborne: N95 and negative-pressure room', 'Droplet only', 'Standard only'], ['Contacto', 'Aérea: N95 y habitación con presión negativa', 'Solo gotas', 'Solo estándar'], 'Measles, TB and varicella are airborne.', 'Sarampión, TB y varicela son de transmisión aérea.'],
    [2, 2, 'Correct order for removing PPE?', '¿Orden correcto para retirar el EPP?', ['Mask, gloves, gown, goggles', 'Gown, mask, gloves, goggles', 'Gloves, goggles, gown, mask, then hand hygiene', 'Goggles, mask, gloves, gown'], ['Mascarilla, guantes, bata, gafas', 'Bata, mascarilla, guantes, gafas', 'Guantes, gafas, bata, mascarilla y luego higiene de manos', 'Gafas, mascarilla, guantes, bata'], 'The most contaminated items come off first; hand hygiene at the end.', 'Lo más contaminado se retira primero; higiene de manos al final.'],
    [1, 0, 'When must you perform hand hygiene?', '¿Cuándo debes hacer higiene de manos?', ['Before touching the patient and after touching their surroundings', 'Only when hands look dirty', 'Only after removing gloves', 'Only before aseptic procedures'], ['Antes de tocar al paciente y después de tocar su entorno', 'Solo si las manos se ven sucias', 'Solo al quitarse los guantes', 'Solo antes de procedimientos asépticos'], 'These are 2 of the 5 moments; the others are before aseptic tasks, after body fluids, after touching the patient.', 'Son 2 de los 5 momentos; los otros: antes de tareas asépticas, tras fluidos y tras tocar al paciente.']
  ],
  'fund-3': [
    [1, 3, 'How do you identify a patient before giving medication?', '¿Cómo identificas al paciente antes de medicar?', ['By room number', 'Ask “Are you Mr. Levi?”', 'By the bed tag only', 'Two identifiers, such as full name and ID number'], ['Por el número de habitación', 'Preguntar “¿Es usted el Sr. Levi?”', 'Solo por la etiqueta de la cama', 'Dos identificadores, como nombre completo y número de identidad'], 'Ask the patient to state the details; never use the room number.', 'Pide al paciente que diga sus datos; nunca uses el número de habitación.'],
    [2, 1, 'An elderly patient at high fall risk is confused at night. Best plan?', 'Un anciano con alto riesgo de caídas está confuso de noche. ¿Mejor plan?', ['Keep the bed high', 'Bed low, call bell in reach, regular toileting rounds, night light', 'Routine restraints', 'A sedative every night'], ['Cama alta', 'Cama baja, timbre al alcance, rondas para ir al baño, luz nocturna', 'Sujeción rutinaria', 'Un sedante cada noche'], 'Least restrictive prevention measures (circular 145/2019).', 'Medidas de prevención menos restrictivas (circular 145/2019).'],
    [2, 2, 'Intact skin over the sacrum is red and does not blanch. Stage and action?', 'Piel íntegra en el sacro, enrojecida y que no blanquea. ¿Estadio y acción?', ['Stage 2: dry gauze', 'Stage 3: call the surgeon', 'Stage 1: relieve pressure, reposition at least every 2 h, protect the skin', 'Normal, no action'], ['Estadio 2: gasa seca', 'Estadio 3: avisar al cirujano', 'Estadio 1: aliviar presión, reposicionar al menos cada 2 h, proteger la piel', 'Normal, sin acción'], 'Non-blanchable redness on intact skin = stage 1 (circular 153/2019).', 'Eritema que no blanquea en piel íntegra = estadio 1 (circular 153/2019).']
  ],
  'fund-4': [
    [1, 0, 'Which documentation entry is correct?', '¿Qué registro es correcto?', ['10:15 – BP 86/50, Dr. Cohen informed, legs raised', '“Patient seemed fine.”', 'Writing “meds given” before giving them', 'Erasing errors with correction fluid'], ['10:15 – PA 86/50, avisado Dr. Cohen, piernas elevadas', '“El paciente parecía bien.”', 'Escribir “medicación dada” antes de darla', 'Borrar errores con corrector'], 'Timed, factual, includes who was informed and the action.', 'Con hora, objetivo, incluye a quién se avisó y la acción.'],
    [2, 2, 'You wrote an error in the chart. How do you correct it?', 'Escribiste un error en la historia. ¿Cómo lo corriges?', ['Erase it', 'Tear out the page', 'One line through it, write the correct entry, date and sign', 'Leave it'], ['Borrarlo', 'Arrancar la hoja', 'Tachar con una línea, escribir lo correcto, fecha y firma', 'Dejarlo'], 'The original must stay readable.', 'El original debe seguir legible.'],
    [2, 1, 'When must you watch a transfused patient most closely?', '¿Cuándo vigilar más de cerca a un paciente transfundido?', ['The last hour', 'The first 15 minutes', 'Only at the end', 'Not needed if consent was signed'], ['La última hora', 'Los primeros 15 minutos', 'Solo al final', 'No hace falta si firmó'], 'Severe reactions usually start early (circular 11/2020).', 'Las reacciones graves suelen empezar pronto (circular 11/2020).']
  ],
  'medsurg-0': [
    [2, 0, 'A patient with left-sided heart failure wakes up breathless at night. Best position?', 'Un paciente con insuficiencia cardiaca izquierda se despierta sin aire por la noche. ¿Mejor posición?', ['High Fowler with the legs dependent (down)', 'Semi-Fowler with the legs raised on pillows', 'Low Fowler with the knees bent', 'Side-lying with the head of bed at 15°'], ['Fowler alto con las piernas colgando (abajo)', 'Semi-Fowler con las piernas elevadas en almohadas', 'Fowler bajo con las rodillas flexionadas', 'Decúbito lateral con cabecera a 15°'], 'Sitting up with legs down pools blood in the legs and reduces venous return to the congested lungs. Raising the legs does the opposite.', 'Sentado con las piernas abajo acumula sangre en las piernas y reduce el retorno venoso a los pulmones congestionados. Elevar las piernas hace lo contrario.'],
    [2, 2, 'A patient arrives with chest pain. Which blood test do you expect to be sent as the most specific marker of heart muscle damage?', 'Llega un paciente con dolor torácico. ¿Qué análisis esperas que se pida como marcador más específico de daño cardiaco?', ['CK-MB', 'Myoglobin', 'Troponin', 'BNP (natriuretic peptide)'], ['CK-MB', 'Mioglobina', 'Troponina', 'BNP (péptido natriurético)'], 'Troponin is the preferred marker of MI. CK-MB is less specific, myoglobin rises early but is not specific to the heart, and BNP reflects heart failure.', 'La troponina es el marcador preferido del infarto. La CK-MB es menos específica, la mioglobina sube pronto pero no es específica del corazón y el BNP refleja insuficiencia cardiaca.'],
    [2, 3, 'You give discharge teaching to a patient with heart failure. Which instruction about daily weight is correct?', 'Das la educación al alta a un paciente con insuficiencia cardiaca. ¿Qué instrucción sobre el peso diario es correcta?', ['Weigh once a week on the same scale; report a gain over 2.3 kg', 'Weigh daily before bed; report only if ankle swelling also appears', 'Weigh daily after breakfast; report a gain of 3 kg or more in a day', 'Weigh daily at the same time; report 0.9-1.4 kg in a day or 2.3 kg in a week'], ['Pesarse una vez por semana en la misma báscula; avisar si sube más de 2,3 kg', 'Pesarse a diario antes de dormir; avisar solo si también se hinchan los tobillos', 'Pesarse a diario tras el desayuno; avisar si sube 3 kg o más en un día', 'Pesarse a diario a la misma hora; avisar si sube 0,9-1,4 kg en un día o 2,3 kg en una semana'], 'Brunner p.681: daily, same time, same scale, similar clothes (usually morning after voiding). Report 0.9-1.4 kg in a day or 2.3 kg in a week. Weekly weighing misses fast fluid gain.', 'Brunner p.681: a diario, misma hora, misma báscula y ropa similar (por la mañana tras orinar). Avisar si 0,9-1,4 kg en un día o 2,3 kg en una semana. Pesarse semanalmente no detecta la retención rápida.'],
    [3, 2, 'Two hours after a large anterior MI: BP 84/56, HR 118, cool clammy skin, crackles in both lungs, urine 15 mL/h. Most likely?', 'Dos horas tras un infarto anterior extenso: PA 84/56, FC 118, piel fría y sudorosa, crepitantes en ambos pulmones, diuresis 15 mL/h. ¿Lo más probable?', ['Right ventricular infarction', 'Acute pericarditis', 'Cardiogenic shock', 'Hypovolemic shock'], ['Infarto del ventrículo derecho', 'Pericarditis aguda', 'Shock cardiogénico', 'Shock hipovolémico'], 'Pump failure: low BP, poor perfusion and fluid backing up into the lungs. Right ventricular MI causes hypotension with CLEAR lungs and distended neck veins; hypovolemia gives clear lungs; pericarditis gives positional chest pain.', 'Fallo de bomba: PA baja, mala perfusión y líquido acumulado en los pulmones. El infarto del VD da hipotensión con pulmones LIMPIOS e ingurgitación yugular; la hipovolemia da pulmones limpios; la pericarditis, dolor postural.']
  ],
  'medsurg-1': [
    [2, 1, 'You check your patient’s chest drain and see continuous bubbling in the water-seal chamber. What does it mean?', 'Revisas el drenaje torácico de tu paciente y ves burbujeo continuo en la cámara del sello de agua. ¿Qué significa?', ['Normal suction effect: no action is needed', 'A possible air leak: check the connections and notify', 'The tube is blocked: milk and strip the tubing now', 'The lung has fully re-expanded: prepare for removal'], ['Efecto normal de la aspiración: no hace falta actuar', 'Posible fuga de aire: revisar las conexiones y avisar', 'El tubo está obstruido: ordeñar el tubo', 'El pulmón se reexpandió: preparar la retirada'], 'Gentle continuous bubbling is normal in the SUCTION-control chamber. In the WATER-SEAL chamber it suggests an air leak. A blocked tube or re-expanded lung stops tidaling instead.', 'El burbujeo suave continuo es normal en la cámara de ASPIRACIÓN. En la de SELLO DE AGUA sugiere fuga de aire. Un tubo obstruido o un pulmón reexpandido hacen que cese la oscilación.'],
    [3, 0, 'The tracheostomy tube falls out of a mature stoma (6 weeks old). The patient is breathing with difficulty. First action?', 'La cánula de traqueostomía se sale de un estoma maduro (6 semanas). El paciente respira con dificultad. ¿Primera acción?', ['Insert the spare tube with its obturator and call for help', 'Hold the stoma open with a tracheal dilator and wait for the surgeon', 'Give oxygen by face mask and wait for the ENT doctor', 'Cover the stoma and bag-mask ventilate through the mouth'], ['Insertar la cánula de repuesto con su obturador y pedir ayuda', 'Mantener el estoma abierto con un dilatador traqueal y esperar al cirujano', 'Dar oxígeno con mascarilla y esperar al otorrino', 'Cubrir el estoma y ventilar con bolsa-mascarilla por la boca'], 'A mature tract stays open: reinsert the spare tube (kept at the bedside) with the obturator, then remove the obturator. Covering the stoma and bagging is for a fresh stoma or failed reinsertion.', 'Un trayecto maduro se mantiene abierto: reinsertar la cánula de repuesto (junto a la cama) con el obturador y luego retirarlo. Cubrir y ventilar es para un estoma reciente o si falla la reinserción.'],
    [2, 2, 'A trauma patient has SpO2 84% and no lung disease. Which device delivers the highest oxygen concentration?', 'Un paciente traumatizado tiene SpO2 84% y no tiene enfermedad pulmonar. ¿Qué dispositivo aporta la mayor concentración de oxígeno?', ['Nasal cannula 6 L/min', 'Partial rebreather mask 10 L/min', 'Non-rebreather mask 15 L/min', 'Venturi mask set at 50%'], ['Gafas nasales 6 L/min', 'Mascarilla de reinhalación parcial 10 L/min', 'Mascarilla sin reinhalación 15 L/min', 'Mascarilla Venturi al 50%'], 'Non-rebreather ~60-90%. Partial rebreather ~40-70%, Venturi up to about 50%, nasal cannula 6 L/min about 44%.', 'Sin reinhalación ~60-90%. Reinhalación parcial ~40-70%, Venturi hasta ~50%, gafas a 6 L/min ~44%.'],
    [3, 1, 'During an asthma attack the loud wheeze has stopped. The patient now speaks in single words, SpO2 88%. Interpretation?', 'En una crisis asmática las sibilancias fuertes han cesado. Ahora habla con palabras sueltas, SpO2 88%. ¿Interpretación?', ['The bronchospasm is resolving: recheck in 30 minutes', 'Life-threatening: very little air is moving', 'A mucus plug: encourage deep coughing', 'Anxiety-driven: coach slow breathing'], ['El broncoespasmo se resuelve: reevaluar en 30 minutos', 'Riesgo vital: apenas entra aire', 'Un tapón de moco: animar a toser fuerte', 'Por ansiedad: enseñar respiración lenta'], 'A “silent chest” with worse speech and falling SpO2 means severe obstruction, not improvement. Give oxygen and the ordered bronchodilator, and call the rapid response team.', 'Un “tórax silencioso” con peor habla y SpO2 en descenso es obstrucción grave, no mejoría. Oxígeno, broncodilatador prescrito y equipo de respuesta rápida.']
  ],
  'medsurg-2': [
    [2, 3, 'A diabetic patient is admitted vomiting, glucose 480 mg/dL. Which finding fits diabetic ketoacidosis (DKA)?', 'Ingresa un diabético con vómitos y glucosa 480 mg/dL. ¿Qué hallazgo encaja con la cetoacidosis diabética (CAD)?', ['Glucose 900 mg/dL with no ketones and normal pH', 'Sweating, tremor and hunger', 'Slow shallow breathing with pinpoint pupils', 'Deep rapid breathing with a fruity (acetone) breath'], ['Glucosa 900 mg/dL sin cetonas y pH normal', 'Sudor, temblor y hambre', 'Respiración lenta y superficial con pupilas puntiformes', 'Respiración profunda y rápida con aliento afrutado (acetona)'], 'Kussmaul breathing blows off CO2 to compensate the acidosis. Very high glucose without ketones is HHS; sweating and tremor are hypoglycemia; pinpoint pupils suggest opioids.', 'La respiración de Kussmaul elimina CO2 para compensar la acidosis. Glucosa muy alta sin cetonas es EHH; sudor y temblor son hipoglucemia; pupilas puntiformes sugieren opioides.'],
    [2, 0, 'Before discharge you teach a diabetic patient foot care. Which instruction is correct?', 'Antes del alta enseñas el cuidado de los pies a un diabético. ¿Qué instrucción es correcta?', ['Inspect your feet daily (use a mirror) and never walk barefoot', 'Soak your feet in warm water daily to soften calluses', 'Rub moisturizer well between the toes to prevent cracks', 'Cut your nails in a curve that follows the shape of the toe'], ['Revisar los pies a diario (con un espejo) y nunca andar descalzo', 'Remojar los pies en agua tibia a diario para ablandar callos', 'Aplicar crema bien entre los dedos para evitar grietas', 'Cortar las uñas en curva siguiendo la forma del dedo'], 'Daily inspection and footwear prevent unnoticed wounds. Soaking macerates skin, moisture between toes invites fungus, and nails are cut straight across.', 'La inspección diaria y el calzado evitan heridas no detectadas. Remojar macera la piel, la humedad entre los dedos favorece hongos y las uñas se cortan rectas.'],
    [2, 1, 'During IV insulin for DKA, which electrolyte do you watch most closely?', 'Durante la insulina IV en la CAD, ¿qué electrolito vigilas más de cerca?', ['Sodium', 'Potassium', 'Phosphate', 'Magnesium'], ['Sodio', 'Potasio', 'Fosfato', 'Magnesio'], 'Insulin drives potassium into the cells: it can fall fast and cause arrhythmias. Potassium is replaced once urine output is adequate. Phosphate also falls, but less dangerously.', 'La insulina mete el potasio en las células: puede bajar rápido y causar arritmias. Se repone cuando la diuresis es adecuada. El fosfato también baja, pero con menos peligro.'],
    [3, 3, 'Before lunch an alert patient has glucose 62 mg/dL. Insulin lispro 6 units is due with the meal. Best action?', 'Antes de comer un paciente alerta tiene glucosa 62 mg/dL. Toca insulina lispro 6 unidades con la comida. ¿Mejor acción?', ['Give the full lispro dose: the meal will balance it', 'Give half the lispro dose with lunch', 'Hold lunch and recheck the glucose in one hour', 'Treat with 15 g fast carbs, hold the lispro, notify'], ['Dar la dosis completa de lispro: la comida lo compensará', 'Dar la mitad de la lispro con la comida', 'Retrasar la comida y controlar en una hora', 'Tratar con 15 g de hidratos rápidos, retener la lispro, avisar'], 'Treat the hypoglycemia first. Rapid-acting insulin on a low glucose is dangerous, and changing the dose yourself (half a dose) is outside an order: hold and clarify with the prescriber.', 'Primero se trata la hipoglucemia. Insulina rápida con glucosa baja es peligrosa, y cambiar la dosis por tu cuenta (media dosis) no está prescrito: retener y aclarar con quien prescribe.']
  ],
  'medsurg-3': [
    [3, 2, 'K 6.4 mEq/L with peaked T waves. Four drugs are ordered. Which is given FIRST to protect the heart?', 'K 6,4 mEq/L con ondas T picudas. Hay cuatro fármacos prescritos. ¿Cuál se da PRIMERO para proteger el corazón?', ['Regular insulin IV with glucose', 'Sodium polystyrene sulfonate (Kayexalate)', 'IV calcium gluconate', 'Nebulized salbutamol'], ['Insulina rápida IV con glucosa', 'Poliestireno sulfonato sódico (Kayexalate)', 'Gluconato cálcico IV', 'Salbutamol nebulizado'], 'Calcium stabilizes the heart muscle within minutes but does not lower K. Insulin with glucose and salbutamol shift K into cells; Kayexalate or dialysis remove it from the body.', 'El calcio estabiliza el miocardio en minutos pero no baja el K. Insulina con glucosa y salbutamol meten el K en las células; Kayexalate o diálisis lo eliminan.'],
    [2, 1, 'KCl 20 mEq IV is ordered for a patient with K 3.0 mEq/L. How do you give it?', 'Se pauta KCl 20 mEq IV a un paciente con K 3,0 mEq/L. ¿Cómo lo administras?', ['Diluted, as a slow IV push over 5 minutes', 'Diluted, by infusion pump at the ordered rate, never push', 'By gravity drip at up to 40 mEq per hour on a peripheral line', 'Undiluted through a central line by pump'], ['Diluido, en bolo IV lento durante 5 minutos', 'Diluido, con bomba al ritmo prescrito, nunca en bolo', 'Por gravedad hasta 40 mEq por hora por vía periférica', 'Sin diluir por vía central con bomba'], 'KCl is never pushed and never given undiluted. Use a pump; peripheral rates are limited (commonly about 10 mEq/h) per protocol. An independent double check applies.', 'El KCl nunca va en bolo ni sin diluir. Con bomba; la velocidad periférica está limitada (habitualmente unos 10 mEq/h) según protocolo. Requiere doble control independiente.'],
    [3, 0, 'An anxious, hyperventilating patient: pH 7.50, PaCO2 30 mmHg, HCO3 24 mEq/L. Interpretation?', 'Paciente ansioso que hiperventila: pH 7,50, PaCO2 30 mmHg, HCO3 24 mEq/L. ¿Interpretación?', ['Respiratory alkalosis, uncompensated', 'Respiratory alkalosis, fully compensated', 'Metabolic alkalosis, partly compensated', 'Respiratory alkalosis, partly compensated'], ['Alcalosis respiratoria no compensada', 'Alcalosis respiratoria totalmente compensada', 'Alcalosis metabólica parcialmente compensada', 'Alcalosis respiratoria parcialmente compensada'], 'High pH + low CO2 = respiratory alkalosis. HCO3 24 is normal, so no compensation yet. Compensation would show a low HCO3.', 'pH alto + CO2 bajo = alcalosis respiratoria. HCO3 24 es normal: aún no hay compensación. La compensación mostraría un HCO3 bajo.'],
    [3, 0, 'A patient with acute kidney injury. Which finding needs action FIRST?', 'Paciente con lesión renal aguda. ¿Qué hallazgo requiere actuar PRIMERO?', ['K 6.8 mEq/L with an irregular pulse', 'Creatinine 3.2 mg/dL, up from 2.9', 'Urine output 25 mL/h for the last 2 hours', 'BUN 48 mg/dL'], ['K 6,8 mEq/L con pulso irregular', 'Creatinina 3,2 mg/dL, antes 2,9', 'Diuresis 25 mL/h en las últimas 2 horas', 'BUN 48 mg/dL'], 'All four are abnormal, but hyperkalemia with an irregular pulse can cause cardiac arrest within minutes: monitor and treat now. The others are expected in AKI and are reported.', 'Los cuatro son anormales, pero la hiperpotasemia con pulso irregular puede causar parada en minutos: monitorizar y tratar ya. Los demás son esperables en la LRA y se notifican.']
  ],
  'medsurg-4': [
    [1, 1, 'You assess a head-injury patient’s consciousness from 3 to 15. Which scale are you using?', 'Valoras la conciencia de un paciente con TCE de 3 a 15. ¿Qué escala usas?', ['NIH Stroke Scale (NIHSS)', 'Glasgow Coma Scale', 'FOUR score', 'Richmond Agitation-Sedation Scale (RASS)'], ['Escala de ictus NIH (NIHSS)', 'Escala de coma de Glasgow', 'Escala FOUR', 'Escala de agitación-sedación de Richmond (RASS)'], 'GCS: eyes 1-4, verbal 1-5, motor 1-6 = 3-15. NIHSS scores stroke deficits (0-42), FOUR 0-16, RASS from -5 to +4.', 'GCS: ojos 1-4, verbal 1-5, motora 1-6 = 3-15. NIHSS puntúa déficits del ictus (0-42), FOUR 0-16, RASS de -5 a +4.'],
    [2, 1, 'A patient starts having a tonic-clonic seizure in bed. Correct action?', 'Un paciente empieza una crisis tónico-clónica en la cama. ¿Acción correcta?', ['Insert an oral airway or bite block to protect the tongue', 'Turn to the side, cushion the head, loosen clothing, time it', 'Hold the limbs gently to prevent injury', 'Sit the patient up and support the shoulders'], ['Introducir una cánula orofaríngea o mordedor para proteger la lengua', 'Girar de lado, proteger la cabeza, aflojar la ropa, cronometrar', 'Sujetar suavemente las extremidades para evitar lesiones', 'Sentar al paciente y sujetarle los hombros'], 'Nothing goes in the mouth during the seizure and the limbs are never restrained. Side-lying protects the airway; the duration guides treatment (≥5 min = status epilepticus).', 'Nada en la boca durante la crisis y nunca se sujetan las extremidades. De lado protege la vía aérea; la duración guía el tratamiento (≥5 min = estado epiléptico).'],
    [3, 2, 'Head-injury patient: which position helps lower intracranial pressure?', 'Paciente con TCE: ¿qué posición ayuda a bajar la presión intracraneal?', ['Head of bed 30° with the neck flexed forward on a pillow', 'Head of bed 30° with the hips flexed to 90°', 'Head of bed 30°, head and neck in midline', 'Flat, with the legs raised'], ['Cabecera a 30° con el cuello flexionado sobre una almohada', 'Cabecera a 30° con las caderas flexionadas a 90°', 'Cabecera a 30°, cabeza y cuello en línea media', 'Plano, con las piernas elevadas'], 'Midline head and neck keep the jugular veins open. Neck flexion and sharp hip flexion raise ICP; lying flat with legs up raises it too.', 'Cabeza y cuello en línea media mantienen abiertas las yugulares. Flexionar el cuello o las caderas sube la PIC; plano con las piernas arriba también.'],
    [3, 1, 'Stroke symptoms started 2 hours ago. CT shows no bleeding and alteplase is planned. BP is 196/112. Which is correct?', 'Los síntomas de ictus empezaron hace 2 horas. La TC no muestra sangrado y se planea alteplasa. PA 196/112. ¿Qué es correcto?', ['Give alteplase now: time is brain', 'Lower BP below 185/110 first, as ordered', 'Lower the BP quickly to 120/80 before alteplase', 'Give aspirin together with alteplase'], ['Dar alteplasa ya: el tiempo es cerebro', 'Bajar antes la PA a < 185/110, según orden', 'Bajar rápido la PA a 120/80 antes de la alteplasa', 'Dar aspirina junto con la alteplasa'], 'Before thrombolysis BP must be under 185/110 (then under 180/105 for 24 h) to limit bleeding. A fast drop to normal can extend the stroke, and antiplatelets are avoided for 24 h after alteplase.', 'Antes de la trombólisis la PA debe ser < 185/110 (luego < 180/105 durante 24 h) para limitar el sangrado. Bajarla rápido a lo normal puede ampliar el ictus, y se evitan antiagregantes 24 h tras la alteplasa.']
  ],
  'medsurg-5': [
    [2, 0, 'Post-op day 1 after abdominal surgery. Best way to prevent atelectasis?', 'Primer día tras cirugía abdominal. ¿Mejor forma de prevenir la atelectasia?', ['Incentive spirometer about 10 times an hour while awake, early walking', 'Bed rest for 24 hours with the head of bed flat', 'Cough only when secretions are heard, to protect the incision', 'Oxygen 4 L/min by nasal cannula until discharge'], ['Inspirómetro unas 10 veces por hora y caminar pronto', 'Reposo en cama 24 horas con la cabecera plana', 'Toser solo si se oyen secreciones, para proteger la herida', 'Oxígeno 4 L/min por gafas nasales hasta el alta'], 'Deep breaths open the alveoli: incentive spirometer, splinted coughing and early ambulation. Oxygen treats hypoxia but does not re-open collapsed alveoli.', 'Las respiraciones profundas abren los alvéolos: inspirómetro, tos con la herida sujeta y deambulación precoz. El oxígeno trata la hipoxia pero no reabre alvéolos colapsados.'],
    [2, 3, 'An alert stroke patient has a weak cough and a wet voice. What is done before the first meal?', 'Un paciente alerta tras un ictus tiene tos débil y voz húmeda. ¿Qué se hace antes de la primera comida?', ['Start with thin liquids to test the swallow', 'Give soft food with the head of bed at 30°', 'Check the gag reflex; if present, start a regular diet', 'A swallow screen before any food, fluid or oral medication'], ['Empezar con líquidos finos para probar la deglución', 'Dar comida blanda con la cabecera a 30°', 'Comprobar el reflejo nauseoso; si está, dieta normal', 'Cribado de deglución antes de nada por boca'], 'A screen by a trained RN comes before anything by mouth. A present gag reflex does not prove a safe swallow, and thin liquids are the most likely to be aspirated. Eat sitting upright at 90°.', 'Un cribado por una enfermera formada va antes de nada por boca. Tener reflejo nauseoso no garantiza una deglución segura y los líquidos finos son los que más se aspiran. Comer sentado a 90°.'],
    [2, 1, 'An older woman with mild dementia is suddenly much more confused and has burning urination. Most likely?', 'Una mujer mayor con demencia leve está de repente mucho más confusa y tiene escozor al orinar. ¿Lo más probable?', ['Natural progression of her Alzheimer dementia', 'Delirium caused by a urinary tract infection', 'Sundowning, expected in the evenings', 'Late-onset psychosis'], ['Progresión natural de su demencia de Alzheimer', 'Delirium causado por una infección urinaria', 'Síndrome del ocaso, esperable por la tarde', 'Psicosis de inicio tardío'], 'A sudden change on top of dementia is delirium until proven otherwise. In older adults a UTI often shows as confusion. Dementia worsens slowly.', 'Un cambio brusco sobre una demencia es delirium hasta demostrar lo contrario. En mayores, la infección urinaria se presenta a menudo como confusión. La demencia empeora despacio.'],
    [3, 2, 'Day 3 after a hip replacement: sudden breathlessness, sharp chest pain on breathing in, HR 118, SpO2 87%. Most likely?', 'Día 3 tras una prótesis de cadera: disnea brusca, dolor torácico punzante al inspirar, FC 118, SpO2 87%. ¿Lo más probable?', ['Atelectasis', 'Hospital-acquired pneumonia', 'Pulmonary embolism', 'Anxiety and pain'], ['Atelectasia', 'Neumonía nosocomial', 'Embolia pulmonar', 'Ansiedad y dolor'], 'Orthopedic surgery and immobility raise the risk of DVT and PE. Sudden onset with pleuritic pain, tachycardia and hypoxia fits PE. Atelectasis and pneumonia develop gradually, pneumonia with fever.', 'La cirugía ortopédica y la inmovilidad aumentan el riesgo de TVP y EP. Inicio brusco con dolor pleurítico, taquicardia e hipoxia encaja con EP. La atelectasia y la neumonía son graduales, la neumonía con fiebre.']
  ],
  'pharm-0': [
    [1, 2, 'On your medication round, which of these needs an independent double check before you give it?', 'En tu ronda de medicación, ¿cuál de estos necesita doble control independiente antes de darlo?', ['IV ceftriaxone 1 g', 'Oral amlodipine 5 mg', 'Subcutaneous insulin', 'Oral paracetamol 1 g'], ['Ceftriaxona IV 1 g', 'Amlodipino oral 5 mg', 'Insulina subcutánea', 'Paracetamol oral 1 g'], 'Insulin is a high-alert medication: an error can cause severe harm. Others on the list: anticoagulants, opioids, concentrated potassium, chemotherapy.', 'La insulina es de alto riesgo: un error puede causar daño grave. Otros: anticoagulantes, opioides, potasio concentrado, quimioterapia.'],
    [2, 0, 'A medication order is unclear. What do you do?', 'Una orden de medicación no está clara. ¿Qué haces?', ['Clarify with the prescriber before giving', 'Give the dose that matches the drug reference book', 'Give what the pharmacist suggests, then tell the prescriber', 'Give yesterday’s dose and clarify on the next round'], ['Aclararla con quien la prescribió antes de darla', 'Dar la dosis que coincide con el vademécum', 'Dar lo que sugiera el farmacéutico y luego avisar al médico', 'Dar la dosis de ayer y aclararla en la próxima ronda'], 'Only the prescriber can clarify an order. The pharmacist and the reference book help you understand it but cannot replace a clear order.', 'Solo quien prescribe puede aclarar una orden. El farmacéutico y el vademécum ayudan a entenderla, pero no sustituyen una orden clara.'],
    [2, 3, 'The patient says: “This pill looks different from the one I usually take.” Best response?', 'El paciente dice: “Esta pastilla es distinta de la que tomo siempre.” ¿Mejor respuesta?', ['Explain that generic brands often look different, and give it', 'Give it and document the patient’s concern', 'Hold it and wait for the next medication round', 'Stop, and re-check the order and the medication before giving'], ['Explicar que los genéricos suelen ser distintos y darla', 'Darla y registrar la duda del paciente', 'Retenerla y esperar a la siguiente ronda', 'Detenerse y comprobar de nuevo la orden y el fármaco'], 'A patient’s doubt is a safety check: verify before giving. It may well be a generic, but you only know after re-checking.', 'La duda del paciente es un control de seguridad: verificar antes de dar. Puede ser un genérico, pero solo lo sabes tras comprobarlo.'],
    [3, 1, 'Which is the correct way to identify a patient before giving medication?', '¿Cuál es la forma correcta de identificar al paciente antes de dar la medicación?', ['Ask “Are you Mr. Cohen?” and check the bed number', 'Have him state his full name and ID, and match the wristband', 'Check the name on the door and the medication cart', 'Ask the family member at the bedside to confirm his name'], ['Preguntar “¿Es usted el Sr. Cohen?” y comprobar la cama', 'Que diga su nombre completo e ID, y cotejar con la pulsera', 'Comprobar el nombre de la puerta y del carro', 'Pedir al familiar presente que confirme el nombre'], 'Two identifiers, stated by the patient (not yes/no) and matched to the wristband and the order. Room and bed numbers are never identifiers, and a confused patient may answer “yes” to any name.', 'Dos identificadores dichos por el paciente (no sí/no) y cotejados con la pulsera y la orden. Habitación y cama nunca identifican, y un paciente confuso puede decir “sí” a cualquier nombre.']
  ],
  'pharm-1': [
    [2, 1, 'Before metoprolol: HR 52/min, BP 92/58. What do you do?', 'Antes del metoprolol: FC 52/min, PA 92/58. ¿Qué haces?', ['Give it: beta-blockers are expected to slow the heart', 'Hold it and notify the physician', 'Give half the dose and recheck in one hour', 'Give it and teach the patient to rise slowly'], ['Darlo: es esperable que el betabloqueante baje la FC', 'Retenerlo y avisar al médico', 'Dar media dosis y repetir en una hora', 'Darlo y enseñar a levantarse despacio'], 'Bradycardia and low BP: hold and report (common hold parameters: HR under 60, systolic under 90-100). A half dose is a change of order the nurse cannot make alone.', 'Bradicardia y PA baja: retener y avisar (parámetros habituales: FC < 60, sistólica < 90-100). Media dosis es cambiar la orden, algo que la enfermera no decide sola.'],
    [2, 1, 'Which side effect of enalapril often makes patients stop taking it?', '¿Qué efecto adverso del enalapril hace a menudo que se abandone?', ['Ankle swelling', 'Dry cough', 'Low potassium', 'A slow heart rate'], ['Edema de tobillos', 'Tos seca', 'Potasio bajo', 'Frecuencia cardiaca lenta'], 'ACE inhibitors cause a dry cough and can RAISE potassium. Ankle swelling is typical of calcium-channel blockers (amlodipine); a slow heart rate, of beta-blockers.', 'Los IECA causan tos seca y pueden SUBIR el potasio. El edema de tobillos es típico de los antagonistas del calcio (amlodipino); la bradicardia, de los betabloqueantes.'],
    [2, 0, 'A patient on digoxin and furosemide has nausea and sees yellow-green halos. Best action?', 'Un paciente con digoxina y furosemida tiene náuseas y ve halos amarillo-verdes. ¿Mejor acción?', ['Toxicity: hold it, check level and potassium, notify', 'Expected effect: give digoxin with food and an antiemetic', 'Suspect migraine aura: give the PRN analgesic', 'Suspect cataract: refer to the eye clinic after discharge'], ['Toxicidad: retenerla, pedir nivel y potasio, avisar', 'Efecto esperable: dar la digoxina con comida y un antiemético', 'Sospechar aura migrañosa: dar el analgésico a demanda', 'Sospechar catarata: derivar a oftalmología al alta'], 'GI upset plus visual changes are classic digoxin toxicity. Furosemide lowers potassium, which makes toxicity more likely.', 'Molestias digestivas y cambios visuales son la toxicidad clásica. La furosemida baja el potasio y eso la favorece.'],
    [3, 2, 'A patient on furosemide has potassium 3.1 mEq/L and an apical pulse of 64/min. Digoxin is due. Best action?', 'Un paciente con furosemida tiene potasio 3,1 mEq/L y pulso apical 64/min. Toca la digoxina. ¿Mejor acción?', ['Give it: the pulse is above 60', 'Give it with a potassium-rich snack', 'Hold it and report the low potassium', 'Give the furosemide first, then the digoxin'], ['Darla: el pulso es mayor de 60', 'Darla con un tentempié rico en potasio', 'Retenerla y avisar al médico del potasio bajo', 'Dar primero la furosemida y luego la digoxina'], 'The pulse passes, but hypokalemia makes digoxin toxicity much more likely. Report it: the potassium is corrected first. Food cannot correct 3.1 safely, and furosemide lowers potassium further.', 'El pulso es aceptable, pero la hipopotasemia hace mucho más probable la toxicidad. Avisar: primero se corrige el potasio. La comida no corrige un 3,1 con seguridad y la furosemida lo baja aún más.']
  ],
  'pharm-2': [
    [1, 2, 'Your patient started warfarin for atrial fibrillation. Which test will you follow to monitor it?', 'Tu paciente empezó warfarina por fibrilación auricular. ¿Qué prueba seguirás para controlarla?', ['aPTT', 'Anti-Xa level', 'INR', 'Platelet count'], ['TTPa', 'Nivel anti-Xa', 'INR', 'Recuento de plaquetas'], 'Warfarin is monitored by INR (PT). aPTT monitors IV heparin, anti-Xa monitors low-molecular-weight heparin when needed, and platelets are watched for HIT with heparin.', 'La warfarina se controla con INR (TP). El TTPa controla la heparina IV, el anti-Xa la HBPM si hace falta, y las plaquetas se vigilan por TIH con heparina.'],
    [2, 1, 'You are about to give enoxaparin (Clexane) from a prefilled syringe. Correct technique?', 'Vas a administrar enoxaparina (Clexane) en jeringa precargada. ¿Técnica correcta?', ['SC in the abdomen; expel the air bubble first, then massage gently', 'SC in the abdomen at least 5 cm from the navel; keep the bubble, do not rub', 'SC in the thigh; aspirate before injecting', 'SC 1 cm from the navel; rub afterwards to reduce bruising'], ['SC en el abdomen; expulsar la burbuja antes y masajear suave', 'SC en el abdomen a ≥5 cm del ombligo; mantener la burbuja, no frotar', 'SC en el muslo; aspirar antes de inyectar', 'SC a 1 cm del ombligo; frotar después para evitar hematomas'], 'The air bubble stays in the syringe so the full dose is given. No aspiration and no rubbing: both cause bruising. Keep at least 5 cm from the navel and rotate sides.', 'La burbuja se queda para que pase toda la dosis. Sin aspirar ni frotar: ambos causan hematomas. A ≥5 cm del ombligo y alternando lados.'],
    [3, 3, 'Naloxone woke a patient with morphine overdose. 45 minutes later RR is 8/min again. Why?', 'La naloxona despertó a un paciente con sobredosis de morfina. 45 minutos después la FR vuelve a ser 8/min. ¿Por qué?', ['An allergic reaction to naloxone', 'Opioid withdrawal caused by naloxone', 'The morphine dose was given twice', 'Naloxone wears off before morphine does'], ['Una reacción alérgica a la naloxona', 'Abstinencia de opioides causada por la naloxona', 'La dosis de morfina se dio dos veces', 'La naloxona dura menos que la morfina'], 'Naloxone acts for about 30-90 minutes, shorter than many opioids, so sedation can return. Keep monitoring RR and sedation after reversal; withdrawal causes agitation, not sedation.', 'La naloxona dura unos 30-90 minutos, menos que muchos opioides, y la sedación puede volver. Vigilar FR y sedación tras revertir; la abstinencia causa agitación, no sedación.'],
    [3, 0, 'Day 7 of heparin: platelets fell from 250,000 to 110,000/µL and a new leg clot is suspected. What do you expect?', 'Día 7 de heparina: las plaquetas bajaron de 250.000 a 110.000/µL y se sospecha un trombo nuevo en la pierna. ¿Qué esperas?', ['Stop all heparin, including flushes, and notify', 'Switch to enoxaparin, which is safe to use in HIT', 'Continue heparin and transfuse platelets', 'Give protamine and continue at a lower dose'], ['Suspender toda heparina, también lavados, y avisar', 'Cambiar a enoxaparina, que es segura de usar en la TIH', 'Seguir con heparina y transfundir plaquetas', 'Dar protamina y seguir a dosis menor'], 'A fall of 50% or more after 5-10 days with new clotting suggests heparin-induced thrombocytopenia. All heparin stops (including LMWH and flushes); a non-heparin anticoagulant is started by order.', 'Una caída ≥50% a los 5-10 días con trombosis nueva sugiere TIH. Se suspende toda heparina (también HBPM y lavados) y se inicia un anticoagulante no heparínico por orden.']
  ],
  'pharm-3': [
    [2, 0, 'A patient with suspected sepsis has a first dose of IV antibiotic ordered. What must happen BEFORE it is given?', 'Un paciente con sospecha de sepsis tiene prescrita la primera dosis de antibiótico IV. ¿Qué debe hacerse ANTES de darla?', ['Ask about allergies and draw the ordered cultures', 'Draw cultures and wait for the result before giving it', 'Check the creatinine and give it only if normal', 'Give it, then draw the cultures within an hour'], ['Preguntar por alergias y extraer los cultivos prescritos', 'Extraer cultivos y esperar el resultado antes de darlo', 'Comprobar la creatinina y darlo solo si es normal', 'Darlo y extraer los cultivos en la hora siguiente'], 'Allergies first, cultures before the first dose (antibiotics can make them negative), then give without delay. Waiting for the result or for normal kidney tests delays treatment.', 'Primero alergias, cultivos antes de la primera dosis (el antibiótico puede negativizarlos) y luego darlo sin demora. Esperar resultados o la función renal retrasa el tratamiento.'],
    [2, 2, 'During a vancomycin infusion the face, neck and upper chest become red and itchy; BP is stable. Action?', 'Durante una perfusión de vancomicina la cara, el cuello y el tórax se enrojecen y pican; PA estable. ¿Acción?', ['Continue at the same rate: flushing is expected', 'Stop it permanently and record a vancomycin allergy', 'Slow or pause the infusion and notify the physician', 'Give IM epinephrine and call the resuscitation team'], ['Seguir al mismo ritmo: el rubor es esperable', 'Suspenderla para siempre y registrar alergia a vancomicina', 'Enlentecer o pausar la perfusión y avisar al médico', 'Dar adrenalina IM y llamar al equipo de reanimación'], 'Vancomycin infusion reaction (“red man”) comes from infusing too fast and is not a true allergy. Slow it (usually over at least 60 minutes); an antihistamine may be ordered. Epinephrine is for anaphylaxis with low BP or breathing trouble.', 'La reacción por infusión de vancomicina (“hombre rojo”) se debe a la velocidad y no es alergia. Se enlentece (≥60 minutos); puede prescribirse antihistamínico. La adrenalina es para anafilaxia con hipotensión o dificultad respiratoria.'],
    [2, 2, 'A healthy adult patient going home asks how much paracetamol she may take. Maximum per day?', 'Una paciente adulta sana que se va a casa pregunta cuánto paracetamol puede tomar. ¿Máximo al día?', ['2 g', '3 g', '4 g', '6 g'], ['2 g', '3 g', '4 g', '6 g'], 'Healthy adult: 4 g a day. Lower limits (often 2-3 g) apply to liver disease, regular alcohol use or low body weight. Count hidden paracetamol in combination products.', 'Adulto sano: 4 g al día. Límites menores (2-3 g) en hepatopatía, consumo habitual de alcohol o bajo peso. Contar el paracetamol oculto en combinaciones.'],
    [3, 3, 'A post-op patient has a morphine PCA. Which finding is the EARLIEST warning of opioid-induced respiratory depression?', 'Un paciente posoperado tiene PCA de morfina. ¿Qué hallazgo es el aviso MÁS PRECOZ de depresión respiratoria por opioides?', ['SpO2 falling from 97% to 93% on oxygen', 'Respiratory rate of 12/min while asleep', 'Pinpoint pupils on both sides', 'Increasing sedation, dozing off mid-sentence'], ['SpO2 que baja de 97% a 93% con oxígeno', 'Frecuencia respiratoria de 12/min dormido', 'Pupilas puntiformes en ambos ojos', 'Sedación creciente: se duerme a mitad de frase'], 'Sedation increases before breathing slows. Assess sedation with every RR check and hold opioids if he is hard to keep awake. On oxygen SpO2 falls late; pinpoint pupils show opioid effect, not danger.', 'La sedación aumenta antes de que baje la respiración. Valorar la sedación con cada FR y retener opioides si cuesta mantenerlo despierto. Con oxígeno la SpO2 cae tarde; la miosis indica efecto opioide, no peligro.']
  ],
  'peds-0': [
    [1, 2, 'At what age does a baby usually start walking alone?', '¿A qué edad suele empezar un bebé a caminar solo?', ['6 months', '9 months', '12 months', '18 months'], ['6 meses', '9 meses', '12 meses', '18 meses'], 'Sits alone ~6-8 months, pulls to stand ~9 months, walks ~12 months. Not walking by 18 months needs evaluation.', 'Se sienta ~6-8 meses, se pone de pie ~9 meses, camina ~12 meses. No caminar a los 18 meses requiere valoración.'],
    [2, 0, 'Best way to prepare a 2-year-old for a procedure?', '¿Mejor forma de preparar a un niño de 2 años para un procedimiento?', ['Just before, in simple words, with a parent close', 'Explain 2-3 days ahead using pictures of the body', 'Ask the parent to wait outside so the child cooperates', 'Give a detailed explanation and let the child ask questions'], ['Justo antes, con palabras simples y un padre cerca', 'Explicar 2-3 días antes con dibujos del cuerpo', 'Pedir al padre que espere fuera para que coopere', 'Dar una explicación detallada y dejar que pregunte'], 'Toddlers have little sense of time and fear separation most: prepare right before, keep parents present, offer simple choices. Days-ahead preparation with pictures suits school-age children.', 'Los niños pequeños apenas entienden el tiempo y temen sobre todo la separación: preparar justo antes, con los padres, con opciones simples. Preparar días antes con dibujos es para la edad escolar.'],
    [2, 2, 'How do you protect a teenager’s privacy?', '¿Cómo proteges la intimidad de un adolescente?', ['Interview the teen and parents together for an accurate history', 'Promise to keep everything the teen says secret', 'Offer time alone and explain the limits of confidentiality', 'Share all findings with the parents because the teen is a minor'], ['Entrevistar juntos al adolescente y a los padres para una historia exacta', 'Prometer guardar en secreto todo lo que diga', 'Ofrecer tiempo a solas y explicar los límites de la confidencialidad', 'Compartir todo con los padres porque es menor'], 'Teens deserve time alone and confidentiality, but you never promise total secrecy: risk of harm to self or others, or abuse, must be reported.', 'Los adolescentes merecen tiempo a solas y confidencialidad, pero nunca se promete secreto total: el riesgo de daño o el maltrato se notifican.'],
    [3, 1, 'An 18-month-old cried and clung to the door when the parents left. Now, a day later, he is quiet, withdrawn and not interested in play. This stage is:', 'Un niño de 18 meses lloró y se aferró a la puerta cuando se fueron los padres. Un día después está callado, retraído y sin interés por jugar. Esta fase es:', ['Protest', 'Despair', 'Detachment', 'Healthy adjustment'], ['Protesta', 'Desesperación', 'Desapego', 'Adaptación sana'], 'Separation anxiety: protest (crying, clinging), then despair (quiet, withdrawn, sad), then detachment (seems to adjust but has given up; rare in short stays). Quiet does not mean settled.', 'Ansiedad por separación: protesta (llanto, aferrarse), luego desesperación (callado, retraído, triste) y luego desapego (parece adaptado pero se ha rendido; raro en estancias cortas). Callado no significa adaptado.']
  ],
  'peds-1': [
    [1, 1, 'You count the heart rate of a calm newborn on the postnatal ward. Which range is typical?', 'Cuentas la frecuencia cardiaca de un recién nacido tranquilo en la planta. ¿Qué rango es típico?', ['80-100/min', '100-160/min', '70-110/min', '160-200/min'], ['80-100/min', '100-160/min', '70-110/min', '160-200/min'], 'Newborn about 100-160/min (lower in deep sleep). 70-110 fits a school-age child; under 100 in a newborn needs attention.', 'Recién nacido ~100-160/min (menos en sueño profundo). 70-110 es de edad escolar; < 100 en un neonato requiere atención.'],
    [2, 3, 'Which finding suggests dehydration in an infant?', '¿Qué hallazgo sugiere deshidratación en un lactante?', ['Bulging fontanelle with irritability', 'Capillary refill of 1-2 seconds', 'Tears when crying and moist mouth', 'Sunken fontanelle and fewer wet diapers'], ['Fontanela abombada con irritabilidad', 'Relleno capilar de 1-2 segundos', 'Lágrimas al llorar y boca húmeda', 'Fontanela hundida y menos pañales mojados'], 'Sunken fontanelle, dry mucosa, no tears and fewer wet diapers point to dehydration. A bulging fontanelle suggests raised intracranial pressure (for example meningitis).', 'Fontanela hundida, mucosas secas, sin lágrimas y menos pañales mojados indican deshidratación. Una fontanela abombada sugiere PIC alta (p. ej., meningitis).'],
    [2, 0, 'In what order do you assess a calm toddler sitting on the parent’s lap?', '¿En qué orden valoras a un niño pequeño tranquilo en brazos del padre?', ['Breathing and heart rate first, ears and mouth last', 'Head to toe, starting with eyes, ears and mouth', 'Temperature first, since fever changes the other signs', 'Weight and height first, then the vital signs'], ['Respiración y FC primero, oídos y boca al final', 'De la cabeza a los pies, empezando por ojos, oídos y boca', 'Temperatura primero, porque la fiebre cambia los otros signos', 'Peso y talla primero y luego los signos vitales'], 'Count breathing and heart rate while the child is calm; invasive or upsetting steps (ears, mouth, temperature) come last.', 'Contar respiración y FC mientras está tranquilo; lo invasivo o molesto (oídos, boca, temperatura) va al final.'],
    [3, 0, 'A 2-year-old with vomiting: HR 170, capillary refill 4 s, cool hands, drowsy, BP normal for age. Interpretation?', 'Niño de 2 años con vómitos: FC 170, relleno capilar 4 s, manos frías, somnoliento, PA normal para su edad. ¿Interpretación?', ['Compensated shock: act now', 'Not shock, because the BP is normal', 'Normal heart rate for a toddler who is upset', 'Decompensated shock'], ['Shock compensado: actuar ya', 'No es shock porque la PA es normal', 'FC normal para un niño pequeño alterado', 'Shock descompensado'], 'Children keep their BP up until late. Tachycardia, slow capillary refill, cool skin and drowsiness with a normal BP = compensated shock. Hypotension means decompensation and impending arrest.', 'Los niños mantienen la PA hasta tarde. Taquicardia, relleno lento, piel fría y somnolencia con PA normal = shock compensado. La hipotensión indica descompensación y parada inminente.']
  ],
  'peds-2': [
    [2, 2, 'A 2-year-old has a barking cough, hoarse voice and stridor that worsen at night, with low fever. Likely?', 'Un niño de 2 años tiene tos perruna, voz ronca y estridor que empeoran de noche, con fiebre baja. ¿Probable?', ['Epiglottitis', 'Foreign body aspiration', 'Croup', 'Asthma'], ['Epiglotitis', 'Aspiración de cuerpo extraño', 'Crup', 'Asma'], 'Croup: barking cough, hoarseness, stridor, worse at night, after a cold. Epiglottitis has high fever, drooling and NO barking cough; a foreign body starts suddenly while choking.', 'Crup: tos perruna, ronquera, estridor, peor de noche, tras un catarro. La epiglotitis tiene fiebre alta, babeo y SIN tos perruna; el cuerpo extraño empieza de golpe con atragantamiento.'],
    [3, 1, 'Infant with RSV bronchiolitis, SpO2 93%, feeding poorly. Priority nursing care?', 'Lactante con bronquiolitis por VRS, SpO2 93%, come mal. ¿Cuidado prioritario?', ['Routine bronchodilator nebulizers every 4 hours', 'Nasal suction, fluids, monitor breathing and SpO2', 'Chest physiotherapy every 4 hours', 'Oral antibiotics and steroids'], ['Nebulizaciones de broncodilatador cada 4 horas de rutina', 'Aspiración nasal, líquidos, vigilar respiración y SpO2', 'Fisioterapia respiratoria cada 4 horas', 'Antibióticos y corticoides orales'], 'Bronchiolitis care is supportive: clear the nose (infants breathe through it), keep hydrated, oxygen if needed. Routine bronchodilators, chest physiotherapy, steroids and antibiotics are not recommended.', 'El cuidado es de soporte: despejar la nariz (respiran por ella), hidratar, oxígeno si hace falta. No se recomiendan de rutina broncodilatadores, fisioterapia, corticoides ni antibióticos.'],
    [2, 0, 'You teach the parents of a child with cystic fibrosis. When are the pancreatic enzymes given?', 'Enseñas a los padres de un niño con fibrosis quística. ¿Cuándo se dan las enzimas pancreáticas?', ['With every meal and snack', 'Once a day at bedtime with milk', 'Only with high-fat meals', 'Between meals on an empty stomach'], ['Con cada comida y tentempié', 'Una vez al día al acostarse con leche', 'Solo con comidas ricas en grasa', 'Entre comidas en ayunas'], 'Enzymes work only when food is in the gut: with every meal and snack, adjusted by the team. Fatty, bulky stools mean the dose needs review.', 'Las enzimas solo actúan con comida en el intestino: con cada comida y tentempié, ajustadas por el equipo. Heces grasas y abundantes indican revisar la dosis.'],
    [3, 3, 'A child with croup improved after nebulized epinephrine. Why is he kept for a few hours of observation?', 'Un niño con crup mejoró tras adrenalina nebulizada. ¿Por qué se le observa unas horas?', ['To complete a course of IV antibiotics', 'Epinephrine causes delayed hypoglycemia', 'To wait for the throat culture result', 'Symptoms can return when the drug wears off'], ['Para completar antibióticos IV', 'La adrenalina nebulizada causa hipoglucemia tardía', 'Para esperar el cultivo faríngeo', 'Los síntomas pueden volver al pasar el efecto'], 'Nebulized epinephrine works quickly but briefly, and stridor can rebound. A dose of corticosteroid is given for the longer effect. Croup is viral: no antibiotics.', 'La adrenalina nebulizada actúa rápido pero poco tiempo y el estridor puede volver. Se da un corticoide para el efecto prolongado. El crup es viral: sin antibióticos.']
  ],
  'peds-3': [
    [2, 3, 'A 9-month-old has sudden episodes of crying with legs drawn up, then calm periods, and a red currant-jelly stool. Suspect?', 'Un bebé de 9 meses tiene episodios súbitos de llanto con las piernas encogidas, luego calma, y heces en jalea de grosella. ¿Sospecha?', ['Pyloric stenosis', 'Meckel diverticulum', 'Hirschsprung disease', 'Intussusception'], ['Estenosis pilórica', 'Divertículo de Meckel', 'Enfermedad de Hirschsprung', 'Invaginación intestinal'], 'Intussusception: colicky pain in bouts, currant-jelly stool, sometimes a sausage-shaped mass. Meckel causes PAINLESS rectal bleeding; Hirschsprung causes constipation from birth.', 'Invaginación: dolor cólico en crisis, heces en jalea de grosella, a veces masa en salchicha. Meckel da sangrado rectal INDOLORO; Hirschsprung, estreñimiento desde el nacimiento.'],
    [2, 2, 'Why must honey be avoided before 12 months of age?', '¿Por qué se evita la miel antes de los 12 meses?', ['It often triggers a severe nut-type allergy', 'Its sugar causes early tooth decay', 'It can contain spores that cause infant botulism', 'It causes rebound hypoglycemia'], ['Suele desencadenar una alergia grave tipo frutos secos', 'Su azúcar causa caries precoz', 'Puede contener esporas que causan botulismo infantil', 'Causa hipoglucemia de rebote'], 'Clostridium botulinum spores in honey can germinate in an infant’s immature gut. Signs: constipation, weak cry, poor feeding, floppiness.', 'Las esporas de Clostridium botulinum de la miel pueden germinar en el intestino inmaduro. Signos: estreñimiento, llanto débil, mala alimentación, hipotonía.'],
    [2, 1, 'A child with chickenpox has a fever. Which drug do you avoid?', 'Un niño con varicela tiene fiebre. ¿Qué fármaco evitas?', ['Paracetamol', 'Aspirin', 'Calamine lotion', 'Oral antihistamine'], ['Paracetamol', 'Aspirina', 'Loción de calamina', 'Antihistamínico oral'], 'Aspirin during viral illness (chickenpox, flu) is linked to Reye syndrome. Paracetamol treats the fever; calamine and antihistamines ease the itch.', 'La aspirina en infecciones virales (varicela, gripe) se asocia al síndrome de Reye. El paracetamol trata la fiebre; la calamina y los antihistamínicos alivian el picor.'],
    [3, 2, 'A toddler with tetralogy of Fallot becomes very blue and breathless while crying. First action?', 'Un niño con tetralogía de Fallot se pone muy cianótico y sin aire al llorar. ¿Primera acción?', ['Sit him upright in high Fowler', 'Lay him flat in Trendelenburg', 'Knee-chest position and oxygen', 'Let him cry to help expand the lungs'], ['Sentarlo en Fowler alto', 'Acostarlo plano en Trendelenburg', 'Posición genupectoral, calmarlo, dar oxígeno', 'Dejar que llore para expandir los pulmones'], 'In a “tet spell”, knees to chest raises systemic resistance and sends more blood to the lungs. Calm the child, give oxygen and the ordered drugs (for example morphine). Crying makes it worse.', 'En la crisis hipoxémica, rodillas al pecho aumenta la resistencia sistémica y envía más sangre al pulmón. Calmar, oxígeno y fármacos prescritos (p. ej., morfina). Llorar lo empeora.']
  ],
  'peds-4': [
    [1, 0, 'Safe sleep for an infant?', '¿Sueño seguro para un lactante?', ['On the back, firm flat mattress, nothing else in the crib', 'On the side, propped with a rolled blanket', 'On the back, with soft bumper pads around the crib', 'On the stomach after feeds to prevent choking'], ['Boca arriba, colchón firme y plano, nada más en la cuna', 'De lado, sujeto con una manta enrollada', 'Boca arriba, con protectores acolchados en la cuna', 'Boca abajo tras las tomas para evitar atragantamientos'], 'Back to sleep, every sleep: firm flat surface with no pillows, bumpers, blankets or toys. Side-lying rolls to prone; healthy babies on their back do not choke more.', 'Boca arriba en cada sueño: superficie firme y plana sin almohadas, protectores, mantas ni juguetes. De lado se gira a boca abajo; boca arriba no se atragantan más.'],
    [1, 2, 'Where do most Israeli infants receive their routine vaccines?', '¿Dónde reciben la mayoría de los lactantes israelíes sus vacunas de rutina?', ['The pediatric emergency room', 'A community pharmacy', 'Tipat Chalav clinic', 'The school health service'], ['Urgencias pediátricas', 'Una farmacia comunitaria', 'Clínica Tipat Jalav', 'El servicio de salud escolar'], 'Tipat Chalav (טיפת חלב) clinics give routine vaccines and track growth from birth to about age 6. School health nurses give the school-age vaccines.', 'Las clínicas Tipat Jalav (טיפת חלב) vacunan y controlan el crecimiento del nacimiento a ~6 años. Las enfermeras escolares ponen las vacunas de edad escolar.'],
    [2, 3, 'Minutes after a vaccine, an infant develops hives, wheezing and pallor. First action?', 'Minutos tras una vacuna, un lactante presenta urticaria, sibilancias y palidez. ¿Primera acción?', ['Oral antihistamine and observe for 30 minutes', 'Salbutamol inhaler and oxygen, then reassess', 'IV hydrocortisone, then epinephrine if BP falls', 'IM epinephrine per protocol and call for help'], ['Antihistamínico oral y observar 30 minutos', 'Salbutamol inhalado y oxígeno, luego reevaluar', 'Hidrocortisona IV y adrenalina si baja la PA', 'Adrenalina IM según protocolo y pedir ayuda'], 'Skin plus breathing signs = anaphylaxis: IM epinephrine in the outer thigh first. Antihistamines, salbutamol and steroids are add-ons, never a replacement.', 'Piel más signos respiratorios = anafilaxia: adrenalina IM en el muslo lateral primero. Antihistamínicos, salbutamol y corticoides son complementos, nunca sustitutos.'],
    [3, 0, 'A mother brings her baby for a routine vaccine. Which finding is a TRUE contraindication to giving it?', 'Una madre trae a su bebé para una vacuna de rutina. ¿Qué hallazgo es una contraindicación VERDADERA para ponerla?', ['Anaphylaxis to a previous dose of the same vaccine', 'A mild cold with a temperature of 37.8 °C', 'Currently taking an antibiotic', 'Redness and soreness at the site after the last dose'], ['Anafilaxia con una dosis previa de la misma vacuna', 'Un catarro leve con 37,8 °C', 'Estar tomando un antibiótico', 'Enrojecimiento y dolor local tras la dosis anterior'], 'Severe allergy to a prior dose or a component is a true contraindication. Mild illness, antibiotics and local reactions are not reasons to delay; delaying leaves the child unprotected.', 'La alergia grave a una dosis previa o a un componente es contraindicación verdadera. Enfermedad leve, antibióticos y reacciones locales no justifican retrasar; retrasar deja al niño sin protección.']
  ],
  'mat-0': [
    [1, 1, 'You connect a woman in labor to the fetal monitor. Which baseline fetal heart rate is normal?', 'Conectas a una mujer de parto al monitor fetal. ¿Qué frecuencia cardiaca fetal basal es normal?', ['100-140/min', '110-160/min', '120-180/min', '160-200/min'], ['100-140/min', '110-160/min', '120-180/min', '160-200/min'], 'Normal baseline 110-160/min. Above 160 for 10 minutes or more is tachycardia; below 110 is bradycardia.', 'Basal normal 110-160/min. Más de 160 durante 10 minutos o más es taquicardia; menos de 110, bradicardia.'],
    [2, 3, 'At admission to the labor ward a woman tells you she is “G3 P1”. What does it mean?', 'Al ingresar en paritorio una mujer te dice que es “G3 P1”. ¿Qué significa?', ['Three births in total, one living child', 'Three pregnancies, one miscarriage', 'Third pregnancy, one living child', 'Third pregnancy, one birth ≥20 weeks'], ['Tres partos en total, un hijo vivo', 'Tres embarazos, un aborto', 'Tercer embarazo, un hijo vivo', 'Tercer embarazo, un parto ≥20 semanas'], 'Gravida = number of pregnancies, including the current one. Para = births after 20 weeks, alive or not. Living children are counted separately (the L in GTPAL).', 'Gesta = número de embarazos, incluido el actual. Para = partos tras 20 semanas, vivos o no. Los hijos vivos se cuentan aparte (la L de GTPAL).'],
    [2, 0, 'Rh-negative mother with a negative antibody screen: when is anti-D immunoglobulin given?', 'Madre Rh negativa con anticuerpos negativos: ¿cuándo se da la inmunoglobulina anti-D?', ['~28 weeks, and within 72 h of an Rh-positive birth', 'Within 72 h after birth only, if the baby is Rh-negative', 'At 28 weeks only, if her antibody screen becomes positive', 'To the newborn within 72 h after birth'], ['~28 semanas y en 72 h tras un parto Rh positivo', 'Solo en las 72 h tras el parto, si el bebé es Rh negativo', 'Solo a las 28 semanas, si sus anticuerpos se positivizan', 'Al recién nacido en las 72 h tras el parto'], 'Anti-D prevents sensitization, so it goes to the MOTHER before antibodies form: about 28 weeks, after bleeding or procedures, and within 72 h after an Rh-positive birth. It is useless once she is sensitized.', 'La anti-D evita la sensibilización: se da a la MADRE antes de que forme anticuerpos (hacia las 28 semanas, tras sangrados o procedimientos y en 72 h tras un parto Rh positivo). No sirve si ya está sensibilizada.'],
    [3, 3, 'At a routine visit at 20 weeks, which finding needs follow-up?', 'En el control rutinario de la semana 20, ¿qué hallazgo requiere seguimiento?', ['Fundal height at the level of the umbilicus', 'Fetal heart rate 145/min', 'Hemoglobin 11.2 g/dL', 'BP 142/92 on two readings'], ['Altura uterina a nivel del ombligo', 'FCF 145/min', 'Hemoglobina 11,2 g/dL', 'PA 142/92 en dos tomas'], 'At 20 weeks the fundus is at the umbilicus, FHR 145 is normal and Hb 11.2 is acceptable in pregnancy. BP of 140/90 or more after 20 weeks is gestational hypertension until proven otherwise: screen for preeclampsia.', 'A las 20 semanas el fondo está en el ombligo, FCF 145 es normal y Hb 11,2 es aceptable en el embarazo. PA ≥140/90 tras la semana 20 es hipertensión gestacional hasta demostrar lo contrario: cribar preeclampsia.']
  ],
  'mat-1': [
    [2, 2, '34 weeks pregnant: BP 158/102, severe headache and seeing spots. Suspect:', '34 semanas: PA 158/102, cefalea intensa y ve puntos. Sospecha:', ['Gestational hypertension without severe features', 'Chronic hypertension', 'Preeclampsia with severe features', 'Migraine with aura'], ['Hipertensión gestacional sin criterios de gravedad', 'Hipertensión crónica', 'Preeclampsia con criterios de gravedad', 'Migraña con aura'], 'New hypertension after 20 weeks plus cerebral or visual symptoms = preeclampsia with severe features, even if BP is below 160/110. It can progress to eclampsia: notify at once.', 'Hipertensión nueva tras la semana 20 con síntomas cerebrales o visuales = preeclampsia grave, aunque la PA sea < 160/110. Puede evolucionar a eclampsia: avisar enseguida.'],
    [2, 1, 'Your patient with preeclampsia is on IV magnesium sulfate. Which assessments detect toxicity?', 'Tu paciente con preeclampsia recibe sulfato de magnesio IV. ¿Qué valoraciones detectan la toxicidad?', ['Blood pressure and blood glucose every hour', 'Reflexes, respiratory rate and urine output', 'Temperature, pulse and the pad count', 'Pupils, headache and fetal movements'], ['Presión arterial y glucemia cada hora', 'Reflejos, frecuencia respiratoria y diuresis', 'Temperatura, pulso y recuento de compresas', 'Pupilas, cefalea y movimientos fetales'], 'Toxicity shows as lost reflexes, RR under 12 and falling urine output (magnesium is cleared by the kidneys). BP is watched too, but it does not detect toxicity.', 'La toxicidad se ve como pérdida de reflejos, FR < 12 y diuresis en descenso (el magnesio se elimina por el riñón). La PA también se vigila, pero no detecta la toxicidad.'],
    [2, 3, 'Third trimester: painful vaginal bleeding with a rigid, board-like, tender uterus. Most likely?', 'Tercer trimestre: sangrado vaginal doloroso con útero rígido, leñoso y doloroso. ¿Lo más probable?', ['Placenta previa', 'Bloody show of normal labor', 'Uterine rupture', 'Placental abruption'], ['Placenta previa', 'Expulsión del tapón mucoso de un parto normal', 'Rotura uterina', 'Desprendimiento de placenta'], 'Abruption: pain, board-like uterus, bleeding that may be less than expected (concealed). Previa is painless; uterine rupture causes sudden tearing pain with contractions stopping, often after a previous cesarean.', 'Desprendimiento: dolor, útero leñoso, sangrado a veces menor de lo esperado (oculto). La previa es indolora; la rotura uterina da dolor desgarrador brusco y cese de contracciones, a menudo con cesárea previa.'],
    [3, 1, 'A woman with preeclampsia has right upper abdominal pain. Which lab pattern fits HELLP syndrome?', 'Una mujer con preeclampsia tiene dolor en hipocondrio derecho. ¿Qué patrón analítico encaja con el síndrome HELLP?', ['Hemolysis, high platelets, low liver enzymes', 'Hemolysis, raised liver enzymes, low platelets', 'Low platelets, normal liver enzymes, high hemoglobin', 'High fibrinogen, raised liver enzymes, normal platelets'], ['Hemólisis, plaquetas altas, enzimas hepáticas bajas', 'Hemólisis, enzimas hepáticas elevadas, plaquetas bajas', 'Plaquetas bajas, enzimas normales, hemoglobina alta', 'Fibrinógeno alto, enzimas elevadas, plaquetas normales'], 'HELLP = Hemolysis, Elevated Liver enzymes, Low Platelets. Right upper or epigastric pain is a warning sign of liver involvement.', 'HELLP = Hemólisis, Enzimas hepáticas elevadas (Elevated Liver), Plaquetas bajas (Low Platelets). El dolor en hipocondrio derecho o epigastrio es una alarma hepática.']
  ],
  'mat-2': [
    [1, 0, 'On the monitor of a woman in active labor you see early decelerations that mirror the contractions. They are caused by:', 'En el monitor de una mujer en trabajo de parto activo ves deceleraciones precoces que reflejan las contracciones. Se deben a:', ['Head compression (benign)', 'Cord compression', 'Placental insufficiency', 'Fetal sleep cycle'], ['Compresión cefálica (benigna)', 'Compresión del cordón', 'Insuficiencia placentaria', 'Ciclo de sueño fetal'], 'Early = head compression (benign). Variable = cord. Late = placental insufficiency. A sleep cycle reduces variability; it does not cause decelerations.', 'Precoz = cabeza (benigna). Variable = cordón. Tardía = insuficiencia placentaria. El sueño fetal reduce la variabilidad; no causa deceleraciones.'],
    [2, 2, 'The membranes rupture during labor. What do you check first?', 'Se rompen las membranas durante el parto. ¿Qué compruebas primero?', ['Colour and odour of the fluid', 'Her temperature', 'The fetal heart rate, right away', 'A nitrazine test to confirm amniotic fluid'], ['Color y olor del líquido', 'Su temperatura', 'La frecuencia cardiaca fetal, enseguida', 'Una prueba de nitrazina para confirmar líquido amniótico'], 'The cord can prolapse when the waters break: check the FHR at once. Fluid colour, odour, amount and time come next; temperature is followed regularly afterwards.', 'El cordón puede prolapsar al romperse la bolsa: comprobar la FCF enseguida. Color, olor, cantidad y hora del líquido después; la temperatura se controla luego de forma periódica.'],
    [2, 1, 'You see the umbilical cord at the vaginal opening. Action?', 'Ves el cordón umbilical en el introito vaginal. ¿Acción?', ['Gently replace the cord into the vagina and call for help', 'Lift the presenting part off the cord, call for help', 'Cover the cord with warm wet gauze and coach her to push', 'High Fowler position with continuous fetal monitoring'], ['Reintroducir con suavidad el cordón en la vagina y pedir ayuda', 'Elevar la presentación, posición genupectoral, pedir ayuda', 'Cubrir el cordón con gasa húmeda tibia y animarla a empujar', 'Fowler alto con monitorización fetal continua'], 'Cord prolapse: relieve pressure (hand lifting the presenting part, knee-chest or Trendelenburg), call for help and prepare for urgent delivery. Do not push the cord back; a wet cover only protects an exposed cord.', 'Prolapso de cordón: aliviar la presión (mano elevando la presentación, genupectoral o Trendelenburg), pedir ayuda y preparar parto urgente. No reintroducir el cordón; la gasa húmeda solo protege un cordón expuesto.'],
    [3, 0, 'During pushing, the monitor shows variable decelerations with good recovery. First nursing action?', 'Durante el expulsivo, el monitor muestra deceleraciones variables con buena recuperación. ¿Primera acción de enfermería?', ['Change her position to relieve cord compression', 'Prepare for an immediate cesarean', 'Increase the oxytocin to shorten labor', 'No action needed: variables are always benign'], ['Cambiarla de posición para liberar el cordón', 'Preparar una cesárea inmediata', 'Subir la oxitocina para acortar el parto', 'Nada: las variables siempre son benignas'], 'Variables come from cord compression. Repositioning is the first step; if they persist or worsen, add the next steps and notify. They are not always benign.', 'Las variables se deben a compresión del cordón. Cambiar de posición es el primer paso; si persisten o empeoran, siguientes medidas y avisar. No siempre son benignas.']
  ],
  'mat-3': [
    [1, 3, 'You are with a mother at a birth. When do you take the newborn’s Apgar score?', 'Acompañas a una madre en el parto. ¿Cuándo valoras el Apgar del recién nacido?', ['At birth and at 1 hour', 'At 5 and 15 minutes', 'At 1 and 10 minutes', 'At 1 and 5 minutes'], ['Al nacer y a la hora', 'A los 5 y 15 minutos', 'Al minuto y a los 10 minutos', 'Al minuto y a los 5 minutos'], 'At 1 and 5 minutes; if the 5-minute score is under 7, it is repeated every 5 minutes. Resuscitation never waits for the score.', 'Al minuto y a los 5 minutos; si a los 5 es < 7, se repite cada 5 minutos. La reanimación nunca espera al Apgar.'],
    [2, 0, 'A term newborn has visible jaundice 12 hours after birth. This is:', 'Un recién nacido a término tiene ictericia visible a las 12 horas de vida. Es:', ['Pathological: report it now', 'Physiological jaundice, common in the first days', 'Breastfeeding jaundice: feed more often', 'Breast-milk jaundice: pause breastfeeding'], ['Patológica: notificar ya', 'Ictericia fisiológica, frecuente los primeros días', 'Ictericia por lactancia: más tomas', 'Ictericia por leche materna: pausar la lactancia'], 'Jaundice in the first 24 hours is pathological (for example hemolysis). Physiological jaundice appears after 24 hours; breast-milk jaundice appears after the first week.', 'La ictericia en las primeras 24 horas es patológica (p. ej., hemólisis). La fisiológica aparece tras 24 horas; la de la leche materna, tras la primera semana.'],
    [2, 2, 'A breastfeeding mother asks how to know her baby gets enough milk. Best answer?', 'Una madre que amamanta pregunta cómo saber si su bebé toma suficiente. ¿Mejor respuesta?', ['The baby sleeps 4-5 hours between feeds', 'Your breasts feel full before every feed', '6+ wet diapers a day after day 4-5', 'The baby drinks 60 mL from a test bottle'], ['El bebé duerme 4-5 horas entre tomas', 'Sientes los pechos llenos antes de cada toma', '6+ pañales mojados al día desde el día 4-5', 'El bebé toma 60 mL de un biberón de prueba'], 'Wet diapers, stools, audible swallowing and weight gain show intake. Long sleeps can mean underfeeding, and breast fullness eases as supply settles.', 'Pañales mojados, deposiciones, deglución audible y aumento de peso indican ingesta. Dormir mucho puede ser falta de alimento, y la sensación de llenura disminuye al regularse la producción.'],
    [3, 2, 'Day 1 after birth: the fundus is 2 cm ABOVE the umbilicus and pushed to the right; bleeding is a little heavier. Most likely cause?', 'Día 1 posparto: el fondo está 2 cm POR ENCIMA del ombligo y desviado a la derecha; sangra algo más. ¿Causa más probable?', ['Normal involution', 'Retained placental fragments', 'A full bladder', 'Endometritis'], ['Involución normal', 'Restos placentarios', 'Vejiga llena', 'Endometritis'], 'A high fundus pushed to one side points to a distended bladder, which also stops the uterus from contracting well. Help her void, then recheck. Normally the fundus is at or below the umbilicus and drops about 1 cm a day.', 'Un fondo alto y desviado indica vejiga distendida, que además impide que el útero se contraiga bien. Ayudarla a orinar y reevaluar. Normalmente está en el ombligo o por debajo y baja ~1 cm al día.']
  ],
  'psych-0': [
    [1, 2, 'An anxious patient is wringing her hands. Most therapeutic response?', 'Una paciente ansiosa se retuerce las manos. ¿Respuesta más terapéutica?', ['“Why are you feeling so anxious?”', '“Don’t worry, the doctors here are excellent.”', '“You seem worried. Tell me about it.”', '“I understand exactly how you feel.”'], ['“¿Por qué estás tan ansiosa?”', '“No te preocupes, los médicos aquí son excelentes.”', '“Te veo preocupada. Cuéntame.”', '“Entiendo exactamente cómo te sientes.”'], 'Name what you observe and invite her to talk. “Why” questions feel like demands, reassurance closes the conversation, and “I know exactly how you feel” is never true.', 'Nombrar lo que observas e invitar a hablar. El “por qué” suena a exigencia, tranquilizar cierra la conversación y “sé exactamente cómo te sientes” nunca es cierto.'],
    [2, 0, 'A patient says the voices tell him he is bad. Best response?', 'Un paciente dice que las voces le dicen que es malo. ¿Mejor respuesta?', ['“I don’t hear them, but I believe you do. What do they say?”', '“The voices aren’t real: they are part of your illness.”', '“Try to ignore them and they will fade.”', '“Why do you think they say you are bad?”'], ['“Yo no las oigo, pero te creo. ¿Qué te dicen?”', '“Las voces no son reales: son parte de tu enfermedad.”', '“Intenta ignorarlas y se irán.”', '“¿Por qué crees que dicen que eres malo?”'], 'Present reality without arguing, accept that the experience is real to him, and ask the content: command hallucinations to harm are a safety risk.', 'Presentar la realidad sin discutir, aceptar que para él es real y preguntar el contenido: las alucinaciones imperativas de daño son un riesgo.'],
    [1, 3, 'A patient with limited Hebrew needs a consent conversation. Who interprets?', 'Un paciente con poco hebreo necesita una conversación de consentimiento. ¿Quién interpreta?', ['Her 16-year-old daughter, who is fluent', 'A Hebrew-speaking cleaner who knows her language', 'A translation app on the nurse’s phone', 'A professional interpreter (in person or by phone)'], ['Su hija de 16 años, que habla con fluidez', 'Un limpiador que habla su idioma', 'Una aplicación de traducción en el móvil de la enfermera', 'Un intérprete profesional (presencial o telefónico)'], 'Consent needs accurate, confidential interpretation: a professional interpreter (Director General circular on cultural and linguistic accessibility). Children, untrained staff and apps risk errors and breaches of privacy.', 'El consentimiento exige interpretación exacta y confidencial: un intérprete profesional (circular sobre accesibilidad cultural y lingüística). Hijos, personal no formado y aplicaciones arriesgan errores y falta de confidencialidad.'],
    [3, 0, 'A severely depressed patient sits silently and answers in single words. Best nursing approach?', 'Un paciente con depresión grave está en silencio y responde con monosílabos. ¿Mejor enfoque?', ['Sit with him briefly, with short simple statements', 'Encourage him to join a lively group activity today', 'Ask many open questions to get him talking', 'Leave him and come back when he is ready to talk'], ['Acompañarlo ratos cortos con frases simples', 'Animarlo a una actividad grupal animada', 'Hacer muchas preguntas abiertas para que hable', 'Dejarlo y volver cuando quiera hablar'], 'Severe depression slows thinking. Silent presence and short, simple statements show acceptance without demands. Many questions or cheerful groups overwhelm him, and leaving him reinforces worthlessness and loses observation.', 'La depresión grave enlentece el pensamiento. La presencia silenciosa y frases cortas muestran aceptación sin exigir. Muchas preguntas o grupos animados lo abruman, y dejarlo refuerza la inutilidad y pierde la observación.']
  ],
  'psych-1': [
    [2, 1, 'Asking a patient directly “Are you thinking of killing yourself?”:', 'Preguntar directamente “¿Estás pensando en suicidarte?”:', ['Should wait until trust is built over several sessions', 'Is recommended and does not increase the risk', 'Is done only if the patient raises the subject first', 'Should be phrased indirectly to avoid planting the idea'], ['Debe esperar a que haya confianza tras varias sesiones', 'Se recomienda y no aumenta el riesgo', 'Solo si el paciente saca el tema', 'Debe hacerse de forma indirecta para no sugerir la idea'], 'Direct, clear questions about suicide are recommended at the first contact and do not plant the idea. Indirect wording lets the risk go unnoticed.', 'Preguntar de forma directa y clara se recomienda desde el primer contacto y no sugiere la idea. Preguntar indirectamente deja pasar el riesgo.'],
    [2, 3, 'Two weeks into antidepressants, a patient is suddenly calm and giving away belongings. This is:', 'A las dos semanas de antidepresivos, un paciente está de repente tranquilo y regala sus cosas. Esto es:', ['Improvement: observation can be reduced', 'A typical side effect of the antidepressant', 'Readiness for discharge planning', 'A warning sign: assess suicide risk now'], ['Mejoría: puede reducirse la observación', 'Un efecto adverso típico del antidepresivo', 'Preparación para planificar el alta', 'Una alarma: valorar el riesgo suicida ya'], 'Energy returns before mood improves, and sudden calm with giving things away can mean a decision has been made. Assess suicide risk now.', 'La energía vuelve antes que el ánimo; la calma repentina y regalar cosas pueden indicar que ha tomado una decisión. Valorar el riesgo ya.'],
    [2, 2, 'An agitated patient is pacing and shouting but has not hurt anyone. First?', 'Un paciente agitado camina y grita, sin haber herido a nadie. ¿Primero?', ['Give the PRN IM sedative right away', 'Apply restraints before he escalates', 'Calm, verbal de-escalation', 'Leave him alone until he calms down'], ['Dar ya el sedante IM a demanda', 'Sujetarlo antes de que vaya a más', 'Desescalar con voz calmada y espacio', 'Dejarlo solo hasta que se calme'], 'Least restrictive first: verbal de-escalation keeping a safe distance and an exit. Medication and restraint come only if de-escalation fails and there is danger; leaving him alone loses observation.', 'Lo menos restrictivo primero: desescalada verbal con distancia segura y salida. Fármacos y sujeción solo si falla y hay peligro; dejarlo solo pierde la observación.'],
    [3, 2, 'Four patients say they feel hopeless. Who is at HIGHEST immediate risk of suicide?', 'Cuatro pacientes dicen sentirse sin esperanza. ¿Quién tiene MAYOR riesgo suicida inmediato?', ['A 25-year-old woman who cuts superficially to relieve tension', 'A 40-year-old with depression, no plan, and a supportive partner', 'A 68-year-old widower who drinks and says he has a gun at home', 'A 30-year-old who says “Sometimes I wish I could disappear”'], ['Una mujer de 25 años que se corta superficialmente para aliviar tensión', 'Un hombre de 40 años con depresión, sin plan y con pareja que lo apoya', 'Un viudo de 68 años que bebe y dice tener un arma en casa', 'Una persona de 30 años que dice “a veces quisiera desaparecer”'], 'Older age, male sex, recent loss, alcohol and access to a lethal means add up to the highest risk. Every expression of hopelessness still needs a direct question about suicide.', 'Edad avanzada, sexo masculino, pérdida reciente, alcohol y acceso a un medio letal suman el mayor riesgo. Toda expresión de desesperanza requiere igualmente preguntar directamente por el suicidio.']
  ],
  'psych-2': [
    [2, 0, 'You assess a patient with schizophrenia. Which finding is a NEGATIVE symptom?', 'Valoras a un paciente con esquizofrenia. ¿Qué hallazgo es un síntoma NEGATIVO?', ['Flat affect and avolition', 'Ideas of reference', 'Loose associations', 'Command hallucinations'], ['Afecto plano y abulia', 'Ideas de referencia', 'Asociaciones laxas', 'Alucinaciones imperativas'], 'Negative symptoms are things that are missing: flat affect, avolition, alogia, social withdrawal. Ideas of reference, loose associations and hallucinations are positive symptoms.', 'Los negativos son lo que falta: afecto plano, abulia, alogia, aislamiento. Ideas de referencia, asociaciones laxas y alucinaciones son positivos.'],
    [2, 2, 'A manic patient will not sit down to eat and is losing weight. Best plan?', 'Un paciente maníaco no se sienta a comer y pierde peso. ¿Mejor plan?', ['Small low-calorie meals at the table with others', 'Let him skip meals until the mania settles', 'High-calorie finger foods he can eat on the move', 'Large meals served in his room'], ['Comidas pequeñas bajas en calorías en la mesa con otros', 'Dejar que salte comidas hasta que se calme', 'Comida hipercalórica que pueda comer caminando', 'Comidas grandes en su habitación'], 'Mania burns energy and limits attention: offer high-calorie, high-protein finger foods and drinks he can take on the move, and monitor weight and intake.', 'La manía gasta mucha energía y limita la atención: comida hipercalórica e hiperproteica para comer con la mano y bebidas que tome caminando; vigilar peso e ingesta.'],
    [2, 1, 'An alcohol-dependent patient needs IV glucose. What is given BEFORE it?', 'Un paciente con dependencia del alcohol necesita glucosa IV. ¿Qué se da ANTES?', ['Folic acid (vitamin B9)', 'Thiamine (vitamin B1)', 'Magnesium', 'Vitamin B12 (cobalamin)'], ['Ácido fólico (vitamina B9)', 'Tiamina (vitamina B1)', 'Magnesio', 'Vitamina B12 (cobalamina)'], 'Glucose without thiamine can trigger Wernicke encephalopathy (confusion, ataxia, eye movement problems). Folate and magnesium are often replaced too, but thiamine comes first.', 'La glucosa sin tiamina puede desencadenar encefalopatía de Wernicke (confusión, ataxia, alteración ocular). Folato y magnesio también suelen reponerse, pero la tiamina va primero.'],
    [3, 0, 'A patient with anorexia nervosa (BMI 13) starts nutritional rehabilitation. Which lab must be watched most closely in the first days?', 'Una paciente con anorexia nerviosa (IMC 13) inicia la renutrición. ¿Qué análisis se vigila más de cerca los primeros días?', ['Phosphate', 'Amylase', 'Cholesterol', 'Albumin'], ['Fosfato', 'Amilasa', 'Colesterol', 'Albúmina'], 'Refeeding syndrome: feeding drives phosphate, potassium and magnesium into the cells; low phosphate can cause heart failure, arrhythmias and death. Feed slowly and check electrolytes daily.', 'Síndrome de realimentación: la nutrición mete fosfato, potasio y magnesio en las células; el fosfato bajo puede causar insuficiencia cardiaca, arritmias y muerte. Realimentar despacio y controlar electrolitos a diario.']
  ],
  'psych-3': [
    [2, 3, 'A patient on clozapine reports a sore throat and fever. Action?', 'Un paciente con clozapina refiere dolor de garganta y fiebre. ¿Acción?', ['Give paracetamol and lozenges, recheck in the morning', 'Take a throat swab and continue clozapine', 'Expected anticholinergic effect: encourage fluids', 'Urgent blood count (neutrophils) and notify the physician'], ['Dar paracetamol y pastillas para la garganta, revisar por la mañana', 'Tomar un frotis faríngeo y seguir con la clozapina', 'Efecto anticolinérgico esperable: más líquidos', 'Hemograma urgente (neutrófilos) y avisar al médico'], 'Clozapine can cause agranulocytosis: any sign of infection needs an urgent neutrophil count, and the drug may have to stop. Regular blood counts are required throughout treatment.', 'La clozapina puede causar agranulocitosis: cualquier signo de infección exige un recuento urgente de neutrófilos y puede haber que suspenderla. Requiere hemogramas periódicos durante todo el tratamiento.'],
    [2, 0, 'Correct teaching for a patient on lithium?', '¿Enseñanza correcta para un paciente con litio?', ['Normal salt and fluids; report vomiting or tremor', 'Follow a low-salt diet to prevent fluid retention', 'Ibuprofen is a safe choice for headaches', 'Stop the lithium once your mood is stable'], ['Sal y líquidos normales; avisar si hay vómitos o temblor', 'Seguir una dieta baja en sal para evitar retención', 'El ibuprofeno es seguro para el dolor de cabeza', 'Dejar el litio cuando el ánimo esté estable'], 'Low salt or fluid loss makes the kidneys keep lithium and the level rises. NSAIDs, ACE inhibitors and diuretics also raise it. Stopping suddenly risks relapse.', 'Poca sal o pérdida de líquidos hacen que el riñón retenga litio y suba el nivel. AINE, IECA y diuréticos también lo suben. Suspender bruscamente arriesga una recaída.'],
    [1, 1, 'A patient who started sertraline asks when she will feel better. Usual answer?', 'Una paciente que empezó sertralina pregunta cuándo se sentirá mejor. ¿Respuesta habitual?', ['1-2 days', '2-4 weeks', '3-4 months', 'Right after the first dose'], ['1-2 días', '2-4 semanas', '3-4 meses', 'Justo tras la primera dosis'], 'Mood improves after about 2-4 weeks, with full effect later. Side effects and returning energy come earlier, which is why suicide risk is watched closely in the first weeks.', 'El ánimo mejora tras ~2-4 semanas y el efecto completo llega después. Los efectos adversos y la energía llegan antes: por eso se vigila el riesgo suicida en las primeras semanas.'],
    [3, 1, 'A patient on sertraline was given tramadol. Now: agitation, sweating, tremor, muscle twitching (clonus), overactive reflexes, temperature 38.8 °C. Suspect:', 'Un paciente con sertralina recibió tramadol. Ahora: agitación, sudor, temblor, sacudidas musculares (clonus), hiperreflexia, temperatura 38,8 °C. Sospecha:', ['Neuroleptic malignant syndrome', 'Serotonin syndrome', 'Anticholinergic toxicity', 'Alcohol withdrawal'], ['Síndrome neuroléptico maligno', 'Síndrome serotoninérgico', 'Toxicidad anticolinérgica', 'Abstinencia alcohólica'], 'Two serotonergic drugs + clonus and hyperreflexia = serotonin syndrome, which develops within hours. NMS develops over days with rigidity and slow reflexes; anticholinergic toxicity gives dry, hot skin.', 'Dos fármacos serotoninérgicos + clonus e hiperreflexia = síndrome serotoninérgico, que aparece en horas. El SNM evoluciona en días con rigidez y reflejos lentos; la toxicidad anticolinérgica da piel seca y caliente.']
  ],
  'emerg-0': [
    [2, 2, 'An adult collapses, is unresponsive and only gasping. First?', 'Un adulto se desploma, no responde y solo boquea. ¿Primero?', ['Give 2 rescue breaths, then call for help', 'Check the carotid pulse for 30 seconds, then call', 'Call for help and an AED, start compressions', 'Open the airway and give 5 breaths before compressions'], ['Dar 2 ventilaciones y luego pedir ayuda', 'Comprobar el pulso carotídeo 30 segundos y luego llamar', 'Pedir ayuda y un DEA, iniciar compresiones', 'Abrir la vía aérea y dar 5 ventilaciones antes de las compresiones'], 'Gasping is not normal breathing: treat as cardiac arrest. Call for help and an AED, and start compressions (C-A-B). A pulse check takes no more than 10 seconds.', 'Boquear no es respirar normal: tratar como parada. Pedir ayuda y un DEA e iniciar compresiones (C-A-B). La comprobación del pulso no dura más de 10 segundos.'],
    [2, 0, 'The AED has just delivered a shock. Next?', 'El DEA acaba de dar una descarga. ¿Siguiente?', ['Resume compressions immediately for 2 minutes', 'Check the pulse for up to 10 seconds, then resume', 'Let the AED re-analyze the rhythm right away', 'Give 2 breaths, then check the pulse'], ['Reanudar compresiones de inmediato durante 2 minutos', 'Comprobar el pulso hasta 10 segundos y luego reanudar', 'Dejar que el DEA reanalice el ritmo enseguida', 'Dar 2 ventilaciones y luego comprobar el pulso'], 'Right after a shock the heart rarely pumps well yet: restart compressions at once. The AED re-analyzes after 2 minutes; no pulse check right after the shock.', 'Justo tras la descarga el corazón rara vez bombea bien: reanudar compresiones enseguida. El DEA reanaliza a los 2 minutos; no se toma el pulso justo después.'],
    [1, 3, 'You are running a resuscitation with an AED. Maximum pause in compressions (for example, for rhythm analysis)?', 'Diriges una reanimación con DEA. ¿Pausa máxima en las compresiones (por ejemplo, para analizar el ritmo)?', ['Under 30 seconds', 'Under 20 seconds', 'Under 15 seconds', 'Under 10 seconds'], ['Menos de 30 segundos', 'Menos de 20 segundos', 'Menos de 15 segundos', 'Menos de 10 segundos'], 'Keep pauses under 10 seconds. Blood flow to the heart and brain drops as soon as compressions stop.', 'Pausas de menos de 10 segundos. El flujo al corazón y al cerebro cae en cuanto se detienen las compresiones.'],
    [3, 2, 'Adult CPR with an advanced airway (endotracheal tube) in place. How are breaths given (AHA 2020)?', 'RCP del adulto con vía aérea avanzada (tubo endotraqueal). ¿Cómo se ventila (AHA 2020)?', ['30:2, pausing compressions for the breaths', '1 breath every 3 seconds with continuous compressions', '1 breath every 6 seconds with continuous compressions', '1 breath every 10 seconds with continuous compressions'], ['30:2, pausando las compresiones para ventilar', '1 ventilación cada 3 segundos con compresiones continuas', '1 ventilación cada 6 segundos con compresiones continuas', '1 ventilación cada 10 segundos con compresiones continuas'], 'With an advanced airway compressions no longer stop: 1 breath every 6 seconds (10/min). Over-ventilation raises chest pressure and reduces blood return to the heart.', 'Con vía aérea avanzada las compresiones no se detienen: 1 ventilación cada 6 segundos (10/min). Ventilar de más sube la presión torácica y reduce el retorno venoso.']
  ],
  'emerg-1': [
    [2, 1, 'A conscious infant is choking. Which action must you NEVER do?', 'Un lactante consciente se atraganta. ¿Qué NUNCA debes hacer?', ['Back blows with the head lower than the chest', 'Abdominal thrusts', 'Chest thrusts with two fingers on the sternum', 'Removing an object you can clearly see in the mouth'], ['Golpes en la espalda con la cabeza más baja que el tórax', 'Compresiones abdominales', 'Compresiones torácicas con dos dedos en el esternón', 'Retirar un objeto que se ve claramente en la boca'], 'Abdominal thrusts can injure an infant’s liver. Back blows and chest thrusts are correct, and a VISIBLE object may be removed; only blind finger sweeps are forbidden.', 'Las compresiones abdominales pueden lesionar el hígado del lactante. Golpes en la espalda y compresiones torácicas son correctos, y un objeto VISIBLE puede retirarse; solo se prohíbe el barrido a ciegas.'],
    [3, 2, 'One rescuer, infant CPR (AHA 2020). Compression technique?', 'Un reanimador, RCP del lactante (AHA 2020). ¿Técnica de compresión?', ['Two-thumb encircling hands', 'Heel of one hand on the upper sternum', 'Two fingers just below the nipple line', 'Two fingers on the xiphoid process'], ['Dos pulgares rodeando el tórax', 'Talón de una mano en la parte alta del esternón', 'Dos dedos justo debajo de la línea de los pezones', 'Dos dedos sobre el apéndice xifoides'], 'Single rescuer: two fingers in the center of the chest just below the nipple line, about 4 cm deep. Two thumbs is the two-rescuer technique; pressing the xiphoid can injure organs.', 'Un reanimador: dos dedos en el centro del tórax justo debajo de la línea de los pezones, unos 4 cm. Dos pulgares es la técnica de dos reanimadores; presionar el xifoides puede lesionar órganos.'],
    [3, 0, 'A child has a pulse but is not breathing adequately. Rescue breathing rate (AHA 2020)?', 'Un niño tiene pulso pero no respira adecuadamente. ¿Frecuencia de ventilación de rescate (AHA 2020)?', ['1 breath every 2-3 seconds (20-30/min)', '1 breath every 3-5 seconds (12-20/min)', '1 breath every 6 seconds (10/min)', '1 breath every 10 seconds (6/min)'], ['1 ventilación cada 2-3 segundos (20-30/min)', '1 ventilación cada 3-5 segundos (12-20/min)', '1 ventilación cada 6 segundos (10/min)', '1 ventilación cada 10 segundos (6/min)'], 'AHA 2020 changed pediatric rescue breathing to 1 breath every 2-3 seconds. Every 3-5 seconds was the older pediatric rule; every 6 seconds is the adult rate.', 'La AHA 2020 cambió la ventilación de rescate pediátrica a 1 cada 2-3 segundos. Cada 3-5 segundos era la regla anterior; cada 6 segundos es la del adulto.'],
    [3, 0, 'You are alone, with no phone, and find a 6-year-old unresponsive and not breathing (collapse not witnessed). First?', 'Estás solo, sin teléfono, y encuentras a un niño de 6 años sin respuesta y sin respirar (colapso no presenciado). ¿Primero?', ['Give about 2 minutes of CPR, then go for help and an AED', 'Leave at once to call for help and get an AED', 'Give 5 rescue breaths, then check the pulse for 30 seconds', 'Check the pulse for 30 seconds before deciding'], ['Hacer unos 2 minutos de RCP y luego ir por ayuda y un DEA', 'Irse enseguida a pedir ayuda y buscar un DEA', 'Dar 5 ventilaciones y luego comprobar el pulso 30 segundos', 'Comprobar el pulso 30 segundos antes de decidir'], 'Children usually arrest from breathing problems, so an unwitnessed collapse gets 2 minutes of CPR first. A witnessed sudden collapse suggests a heart rhythm problem: get the AED first. Pulse checks take no more than 10 seconds.', 'Los niños suelen parar por problemas respiratorios: en colapso no presenciado, 2 minutos de RCP primero. Un colapso súbito presenciado sugiere arritmia: primero el DEA. El pulso no se comprueba más de 10 segundos.']
  ],
  'emerg-2': [
    [2, 3, 'A visitor burns her forearm with hot water in the ward kitchen. First aid?', 'Una visitante se quema el antebrazo con agua caliente en la cocina de la sala. ¿Primeros auxilios?', ['Ice wrapped in a towel for 20 minutes', 'Cool water for 1 minute, then a greasy ointment', 'Cool water, then open large blisters to drain them', 'Cool running water for 10+ minutes, remove rings'], ['Hielo envuelto en una toalla 20 minutos', 'Agua fría 1 minuto y luego una pomada grasa', 'Agua fría y luego abrir las ampollas grandes', 'Agua corriente fría 10+ minutos, retirar anillos'], 'Cool (not icy) running water for at least 10 minutes, and remove jewelry before swelling. Ice damages tissue, grease holds heat, and opened blisters invite infection.', 'Agua corriente fría (no helada) al menos 10 minutos y retirar joyas antes de la hinchazón. El hielo daña el tejido, la grasa retiene calor y abrir ampollas favorece la infección.'],
    [3, 1, 'A leg wound is spurting blood (life-threatening) and a commercial tourniquet is at hand. Per the AHA/Red Cross 2020 first-aid guidelines?', 'Una herida en la pierna sangra a borbotones (riesgo vital) y hay un torniquete comercial a mano. ¿Según las guías de primeros auxilios AHA/Cruz Roja 2020?', ['Direct pressure and elevation; use the tourniquet only if they fail', 'Apply the tourniquet 5-7 cm above the wound now and note the time', 'Press on the femoral pressure point before any tourniquet', 'Apply the tourniquet directly over the wound'], ['Presión directa y elevación; torniquete solo si fallan', 'Torniquete ya, 5-7 cm por encima de la herida, anotar la hora', 'Comprimir el punto femoral antes de cualquier torniquete', 'Aplicar el torniquete justo sobre la herida'], '2020: for life-threatening limb bleeding a tourniquet is first-line when available, placed above (not on) the wound, with the time noted. Elevation and pressure points are no longer recommended.', '2020: en un sangrado de extremidad con riesgo vital, el torniquete es de primera línea si está disponible, por encima (no sobre) la herida y anotando la hora. Ya no se recomiendan la elevación ni los puntos de presión.'],
    [2, 2, 'Anaphylaxis: no improvement a few minutes after the first IM epinephrine. Per circular 204/2023?', 'Anafilaxia: sin mejoría unos minutos tras la primera adrenalina IM. ¿Según la circular 204/2023?', ['Switch to an oral antihistamine and observe', 'Give IV hydrocortisone instead of a second dose', 'Another dose every 3-5 minutes, by physician order', 'Wait 30 minutes before any repeat dose'], ['Pasar a un antihistamínico oral y observar', 'Dar hidrocortisona IV en lugar de otra dosis', 'Otra dosis cada 3-5 minutos, por orden médica', 'Esperar 30 minutos antes de repetir'], 'Repeat IM epinephrine every 3-5 minutes as ordered while there is no improvement. Steroids act too slowly to replace it.', 'Repetir la adrenalina IM cada 3-5 minutos según orden mientras no mejore. Los corticoides actúan demasiado despacio para sustituirla.'],
    [3, 3, 'A runner collapses on a hot day: temperature 41 °C, confused, hot skin. Best first-aid cooling (AHA/Red Cross 2020)?', 'Un corredor se desploma en un día caluroso: 41 °C, confuso, piel caliente. ¿Mejor enfriamiento en primeros auxilios (AHA/Cruz Roja 2020)?', ['Give paracetamol and cool drinks', 'Ice packs to the forehead only', 'Fan him in the shade and wait for the ambulance', 'Immerse the body up to the neck in cold water'], ['Dar paracetamol y bebidas frías', 'Bolsas de hielo solo en la frente', 'Abanicarlo a la sombra y esperar la ambulancia', 'Sumergir el cuerpo hasta el cuello en agua fría'], 'Exertional heat stroke: whole-body cold-water immersion cools fastest. Paracetamol does not work in heat stroke, and a fan or forehead ice is too slow.', 'Golpe de calor por esfuerzo: la inmersión corporal en agua fría enfría más rápido. El paracetamol no sirve en el golpe de calor, y abanico o hielo en la frente son demasiado lentos.']
  ],
  'emerg-3': [
    [2, 0, 'A car-crash victim arrives in the emergency department. In what order do you do the primary survey?', 'Llega a urgencias una víctima de accidente de coche. ¿En qué orden haces la valoración primaria?', ['Airway with C-spine control, then B, C, D, E', 'Airway, Breathing, Circulation, then C-spine once imaging is done', 'Disability (GCS) first, then Airway, Breathing, Circulation', 'Circulation, Airway, Breathing (C-A-B), as in CPR'], ['Vía aérea con control cervical, luego B, C, D, E', 'Vía aérea, Respiración, Circulación y columna cervical tras la imagen', 'Neurológico (GCS) primero y luego vía aérea, respiración, circulación', 'Circulación, vía aérea, respiración (C-A-B), como en la RCP'], 'ABCDE with the cervical spine protected from the start (and any massive external bleeding controlled at once). C-A-B applies to cardiac arrest, not the trauma survey.', 'ABCDE con la columna cervical protegida desde el inicio (y control inmediato de cualquier hemorragia externa masiva). C-A-B es para la parada, no para la valoración del trauma.'],
    [2, 3, 'A patient is bleeding internally after surgery. Which is an EARLY sign of shock you should catch?', 'Un paciente sangra internamente tras una cirugía. ¿Qué signo PRECOZ de shock debes detectar?', ['Systolic BP below 90 mmHg', 'Mottled skin and unresponsiveness', 'Bradycardia with hypotension', 'Fast pulse, restlessness and anxiety'], ['PA sistólica < 90 mmHg', 'Piel moteada y ausencia de respuesta', 'Bradicardia con hipotensión', 'Pulso rápido, inquietud y ansiedad'], 'Compensation comes first: tachycardia, restlessness, cool skin. Low BP, mottling and unresponsiveness mean compensation is failing; bradycardia is a pre-arrest sign.', 'Primero la compensación: taquicardia, inquietud, piel fría. Hipotensión, piel moteada y falta de respuesta indican fallo de la compensación; la bradicardia anuncia la parada.'],
    [2, 2, 'Mass-casualty START triage: patients who can walk are tagged:', 'Triaje START en incidente de múltiples víctimas: quienes pueden caminar se clasifican como:', ['Immediate (red)', 'Delayed (yellow)', 'Minor (green)', 'Expectant (black)'], ['Inmediato (rojo)', 'Diferido (amarillo)', 'Leve (verde)', 'Expectante (negro)'], 'START: “walking wounded” are Minor (green) and re-triaged later. Then each remaining patient is checked for breathing, perfusion and following commands: red, yellow or black.', 'START: los que caminan son Leves (verde) y se reevalúan después. Al resto se les valora respiración, perfusión y obediencia de órdenes: rojo, amarillo o negro.'],
    [3, 1, 'After a car crash: RR 34, HR 128, BP 84/50, distended neck veins, trachea shifted to the left, no breath sounds on the right. Most likely?', 'Tras un accidente de coche: FR 34, FC 128, PA 84/50, yugulares ingurgitadas, tráquea desviada a la izquierda, sin murmullo a la derecha. ¿Lo más probable?', ['Cardiac tamponade', 'Right tension pneumothorax', 'Massive right hemothorax', 'Flail chest'], ['Taponamiento cardiaco', 'Neumotórax a tensión derecho', 'Hemotórax masivo derecho', 'Tórax inestable (volet costal)'], 'Absent breath sounds + trachea pushed away + distended neck veins + shock = tension pneumothorax: immediate decompression. Tamponade has muffled heart sounds with normal breath sounds; massive hemothorax usually has FLAT neck veins.', 'Murmullo ausente + tráquea desplazada + yugulares ingurgitadas + shock = neumotórax a tensión: descompresión inmediata. El taponamiento tiene tonos apagados con murmullo normal; el hemotórax masivo suele tener yugulares PLANAS.']
  ],
  'law-0': [
    [2, 2, 'Who may receive medical information about a competent adult patient?', '¿Quién puede recibir información médica sobre un paciente adulto competente?', ['The spouse and adult children, automatically', 'The employer, with a written request', 'Whoever the patient agreed to, and the team', 'Any relative who shows an ID card'], ['El cónyuge y los hijos adultos, automáticamente', 'El empleador, con una solicitud por escrito', 'Quien el paciente autorizó y el equipo tratante', 'Cualquier familiar que muestre su documento'], 'Medical confidentiality: information goes to the treating team and to whomever the patient agrees to. Family members have no automatic right.', 'Confidencialidad médica: la información va al equipo tratante y a quien el paciente autorice. Los familiares no tienen derecho automático.'],
    [2, 0, 'A patient asks for a copy of his medical record. Under the Patient’s Rights Law:', 'Un paciente pide una copia de su historia clínica. Según la Ley de Derechos del Paciente:', ['He is entitled to it, with narrow exceptions', 'He may receive only the discharge summary', 'He must request it through a lawyer', 'He may receive it only after treatment ends'], ['Tiene derecho a ella, con excepciones limitadas', 'Solo puede recibir el informe de alta', 'Debe pedirla a través de un abogado', 'Solo puede recibirla al terminar el tratamiento'], 'The patient has a right to the information in his record, including a copy. Withholding is a narrow exception for information that could seriously harm his health, decided by a set procedure.', 'El paciente tiene derecho a la información de su historia, incluida una copia. Retenerla es una excepción limitada para información que pueda dañar gravemente su salud, con un procedimiento definido.'],
    [2, 3, 'An unconscious patient in an emergency, with no family present, needs life-saving treatment:', 'Un paciente inconsciente en una urgencia, sin familia presente, necesita un tratamiento que le salve la vida:', ['Wait until a relative is found', 'Ask the court to appoint a guardian first', 'Get approval from the ethics committee first', 'Emergency treatment may be given without consent'], ['Esperar a encontrar a un familiar', 'Pedir primero al tribunal que nombre un tutor', 'Obtener antes la aprobación del comité de ética', 'Puede darse tratamiento urgente sin consentimiento'], 'In a medical emergency, when consent cannot be obtained because of the patient’s condition, urgent treatment may be given. Waiting for relatives, a guardian or a committee would cost the life.', 'En una urgencia médica, si el estado del paciente impide obtener el consentimiento, puede darse tratamiento urgente. Esperar a familiares, un tutor o un comité costaría la vida.'],
    [3, 0, 'A police officer on the ward asks for a patient’s blood alcohol result. There is no court order and no patient consent. What do you do?', 'Un policía en la planta pide el resultado de alcoholemia de un paciente. No hay orden judicial ni consentimiento. ¿Qué haces?', ['Decline, and refer him to the hospital’s legal procedure', 'Give it: police have automatic access to medical records', 'Give it verbally but not in writing', 'Give it if the patient is a suspect in a crime'], ['No revelarlo y remitirlo al procedimiento legal del hospital', 'Dárselo: la policía tiene acceso automático a la historia', 'Decírselo de palabra pero no por escrito', 'Dárselo si el paciente es sospechoso de un delito'], 'Medical confidentiality applies to the police too. Disclosure needs the patient’s consent or a legal basis such as a court order, handled through the hospital’s procedure, not at the bedside.', 'La confidencialidad médica también rige ante la policía. Revelar exige consentimiento del paciente o una base legal como una orden judicial, por el procedimiento del hospital, no junto a la cama.']
  ],
  'law-1': [
    [2, 1, 'A newly arrived immigrant patient asks if she is covered for care. Who is entitled to the health services basket?', 'Una paciente recién inmigrada pregunta si tiene cobertura. ¿Quién tiene derecho a la cesta de servicios de salud?', ['Every citizen, even when living abroad', 'Every resident, through a health fund (kupat cholim)', 'Only residents who have paid health tax for a year', 'Residents and tourists, through Bituach Leumi'], ['Todo ciudadano, aunque viva en el extranjero', 'Todo residente, a través de una caja de salud (kupat jolim)', 'Solo residentes que hayan pagado el impuesto de salud un año', 'Residentes y turistas, a través del Bituaj Leumí'], 'Every Israeli resident is insured and chooses a health fund that provides the basket. Residency, not citizenship, decides; new immigrants are covered from arrival.', 'Todo residente israelí está asegurado y elige una caja de salud que da la cesta. Decide la residencia, no la ciudadanía; los nuevos inmigrantes están cubiertos desde su llegada.'],
    [2, 2, 'A competent dying patient refuses to restart dialysis. What is correct?', 'Un enfermo terminal competente rechaza reanudar la diálisis. ¿Qué es correcto?', ['Respect it only if the family agrees', 'Ask the ethics committee to override the refusal', 'Respect the refusal and continue comfort care', 'Continue dialysis until a court decides'], ['Respetarlo solo si la familia está de acuerdo', 'Pedir al comité de ética que anule el rechazo', 'Respetar el rechazo y continuar los cuidados de confort', 'Seguir con la diálisis hasta que decida un tribunal'], 'The competent dying patient’s wish decides. Not renewing a periodic treatment is allowed, and comfort care continues.', 'Decide la voluntad del enfermo terminal competente. No reanudar un tratamiento periódico está permitido, y los cuidados de confort continúan.'],
    [2, 0, 'How can a patient choose who will decide for him if he loses capacity?', '¿Cómo puede un paciente elegir quién decidirá por él si pierde la capacidad?', ['A medical power of attorney', 'His spouse will decide automatically', 'By telling the treating nurse verbally', 'The treating physician decides alone'], ['Un poder médico', 'Su cónyuge decidirá automáticamente', 'Diciéndoselo de palabra a la enfermera', 'El médico tratante decide solo'], 'A medical power of attorney or an advance directive made according to the law. A spouse does not decide automatically and a verbal remark to staff is not a legal appointment.', 'Un poder médico o unas voluntades anticipadas según la ley. El cónyuge no decide automáticamente y un comentario verbal al personal no es un nombramiento legal.'],
    [3, 2, 'Under the Dying Patient Law, a “dying patient” is one whose life expectancy, despite treatment, is no more than about:', 'Según la Ley del Enfermo Terminal, un “enfermo terminal” es aquel cuya esperanza de vida, pese al tratamiento, no supera aproximadamente:', ['2 weeks', '1 month', '6 months', '1 year'], ['2 semanas', '1 mes', '6 meses', '1 año'], 'A dying patient: incurable, life expectancy up to about 6 months. “Final stage” is a narrower category: about 2 weeks, when more treatments may be withheld.', 'Enfermo terminal: incurable, esperanza de vida de hasta unos 6 meses. La “fase final” es más estrecha: unas 2 semanas, cuando pueden no iniciarse más tratamientos.']
  ],
  'law-2': [
    [1, 3, 'A patient with depression asks to be admitted to the psychiatric ward. Which is the default form of hospitalization?', 'Un paciente con depresión pide ingresar en psiquiatría. ¿Cuál es la forma básica de hospitalización?', ['Compulsory, ordered by the district psychiatrist', 'Court-ordered', 'Urgent hospitalization for observation', 'Voluntary'], ['Forzosa, ordenada por el psiquiatra de distrito', 'Por orden judicial', 'Hospitalización urgente para observación', 'Voluntaria'], 'Voluntary admission with the patient’s consent is the rule. Compulsory and court-ordered admission are exceptions with strict criteria.', 'El ingreso voluntario con consentimiento es la regla. El forzoso y el judicial son excepciones con criterios estrictos.'],
    [2, 1, 'An agitated psychiatric patient may need mechanical restraint. It requires:', 'Un paciente psiquiátrico agitado puede necesitar sujeción mecánica. Requiere:', ['A family request and the nurse’s agreement in writing', 'Physician order, last resort, monitored and documented', 'Nothing special if it is used at night to prevent falls', 'A physician order valid for 7 days without review'], ['Petición de la familia y acuerdo escrito de la enfermera', 'Orden médica, último recurso, vigilada y registrada', 'Nada especial si es de noche para evitar caídas', 'Una orden médica válida 7 días sin revisión'], 'Circular 10/2018: restraint is a last resort, by physician order, for the shortest time, with close monitoring, regular review and full documentation.', 'Circular 10/2018: la sujeción es el último recurso, por orden médica, el menor tiempo posible, con vigilancia estrecha, revisión periódica y registro completo.'],
    [3, 2, 'Who reviews a compulsory psychiatric hospitalization and can order the patient’s release?', '¿Quién revisa una hospitalización psiquiátrica forzosa y puede ordenar el alta?', ['The hospital ethics committee', 'The district court, as the first review', 'The district psychiatric committee', 'The hospital director alone'], ['El comité de ética del hospital', 'El tribunal de distrito, como primera revisión', 'El comité psiquiátrico de distrito', 'Solo el director del hospital'], 'The district psychiatric committee reviews compulsory hospitalization. Its decisions can be appealed to the district court; the ethics committee deals with other matters.', 'El comité psiquiátrico de distrito revisa la hospitalización forzosa. Sus decisiones pueden recurrirse ante el tribunal de distrito; el comité de ética trata otros asuntos.'],
    [3, 3, 'A voluntarily admitted psychiatric patient asks to leave the hospital. Which is correct?', 'Un paciente psiquiátrico ingresado voluntariamente pide irse del hospital. ¿Qué es correcto?', ['He must stay until his family agrees to discharge', 'The nurse may lock the door if he seems unwell', 'He must stay at least 30 days once admitted', 'He may leave, unless a compulsory order is made'], ['Debe quedarse hasta que su familia acepte el alta', 'La enfermera puede cerrar la puerta si lo ve mal', 'Debe quedarse al menos 30 días tras ingresar', 'Puede irse, salvo que se ordene un ingreso forzoso'], 'A voluntary patient may ask to be discharged. Keeping him against his will is lawful only through the compulsory-hospitalization process in the law, never by a family decision or a locked door.', 'Un paciente voluntario puede pedir el alta. Retenerlo contra su voluntad solo es legal por el proceso de hospitalización forzosa de la ley, nunca por decisión familiar ni cerrando la puerta.']
  ],
  'law-3': [
    [2, 0, 'You reasonably suspect child abuse. To whom does the law require you to report?', 'Sospechas razonablemente maltrato infantil. ¿A quién exige la ley que notifiques?', ['A welfare officer or the police', 'The hospital social worker, who decides', 'The child’s family physician', 'The parents, to give them a chance to explain'], ['A un trabajador social oficial o a la policía', 'Al trabajador social del hospital, que decide', 'Al médico de familia del niño', 'A los padres, para que se expliquen'], 'The duty to report is personal: to a welfare officer (pakid sa’ad) or the police. The hospital social worker can help, but passing it on does not replace your duty.', 'El deber de notificar es personal: a un trabajador social oficial (pakid saad) o a la policía. El trabajador social del hospital puede ayudar, pero delegarle no sustituye tu deber.'],
    [2, 3, 'A competent adult woman with injuries says her partner hit her and asks you not to tell anyone. Action?', 'Una mujer adulta competente con lesiones dice que su pareja la golpeó y pide que no lo cuentes. ¿Acción?', ['Report to the police against her will: it is mandatory for all adults', 'Call the partner to hear his side of the story', 'Document it only, and keep it secret as she asked', 'Assess her safety, inform, support and document'], ['Denunciar a la policía contra su voluntad: es obligatorio en todo adulto', 'Llamar a la pareja para oír su versión de los hechos', 'Solo registrarlo y guardar el secreto, como pidió', 'Valorar su seguridad, informar, apoyar y registrar'], 'For a competent adult who is not helpless, the duty is to assess safety, inform, support and document (circular on domestic violence), not to report against her will. Contacting the partner can endanger her.', 'Ante una adulta competente que no está indefensa, el deber es valorar la seguridad, informar, apoyar y registrar (circular de violencia doméstica), no denunciar contra su voluntad. Contactar a la pareja puede ponerla en peligro.'],
    [2, 1, 'A pregnant patient asks you how a termination is arranged. Who approves it in Israel?', 'Una paciente embarazada te pregunta cómo se tramita una interrupción. ¿Quién la aprueba en Israel?', ['The woman’s gynecologist alone', 'An authorized termination committee', 'The district court', 'The woman, with her partner’s written consent'], ['Solo su ginecólogo', 'Un comité autorizado de interrupción del embarazo', 'El tribunal de distrito', 'La mujer, con consentimiento escrito de su pareja'], 'A termination committee approves it under the Penal Law criteria. The partner’s consent is not required.', 'Lo aprueba un comité de interrupción del embarazo según los criterios del Código Penal. No se exige el consentimiento de la pareja.'],
    [3, 1, 'A 16-year-old tells you her stepfather sexually abuses her and begs you not to tell anyone. What do you do?', 'Una chica de 16 años te cuenta que su padrastro abusa sexualmente de ella y te ruega que no lo cuentes. ¿Qué haces?', ['Keep it confidential, since she is over 14 and asked you to', 'Tell her you must report, and report to welfare or the police', 'Report only if she agrees after you explain', 'Tell her mother first so the family can act'], ['Guardar el secreto, porque tiene más de 14 años y lo pidió', 'Explicarle que debes notificar, y hacerlo', 'Notificar solo si acepta tras explicárselo', 'Decírselo primero a la madre para que la familia actúe'], 'She is a minor (under 18), so reasonable suspicion of abuse by a family member must be reported. Be honest that you cannot keep this secret. Telling the family first can put her at risk.', 'Es menor de edad (menos de 18), así que la sospecha razonable de abuso por un familiar debe notificarse. Sé honesta: no puedes guardar este secreto. Avisar antes a la familia puede ponerla en riesgo.']
  ],
  'law-4': [
    [1, 2, 'You take over the narcotics keys at the start of a shift. Which practice is correct?', 'Recibes las llaves de estupefacientes al empezar el turno. ¿Qué práctica es correcta?', ['A locked cabinet, counted once a week', 'Locked, but the key may stay in the cart during busy shifts', 'Locked, counted, every dose documented', 'Stored with regular drugs and recorded in the chart only'], ['Armario cerrado, recuento semanal', 'Bajo llave, pero la llave puede quedarse en el carro en turnos ocupados', 'Bajo llave, contados y cada dosis registrada', 'Junto a los demás fármacos y registrados solo en la historia'], 'Narcotics stay locked with the key held by the responsible nurse, are counted regularly, and every dose is documented in the narcotics register as well as the chart.', 'Los estupefacientes van bajo llave con la llave en poder de la enfermera responsable, se cuentan periódicamente y cada dosis se registra en el libro de estupefacientes y en la historia.'],
    [3, 0, 'A medical intern gives a medication order in the name of the licensed supervising physician. Per the rules on nursing practice:', 'Un médico interno da una orden de medicación en nombre del médico licenciado responsable. Según las normas del ejercicio de enfermería:', ['It may be carried out', 'Only after a senior physician co-signs it', 'Only for oral medications', 'Never: interns may not give orders'], ['Puede ejecutarse', 'Solo cuando un médico senior la refrende', 'Solo para fármacos orales', 'Nunca: los internos no pueden dar órdenes'], 'An intern works under a licensed physician, and an order given in that physician’s name may be carried out. As with any order, the nurse still checks that it is clear and safe.', 'El interno trabaja bajo un médico licenciado, y una orden dada en su nombre puede ejecutarse. Como con toda orden, la enfermera comprueba que sea clara y segura.'],
    [2, 3, 'Who may work as a registered nurse in Israel?', '¿Quién puede trabajar como enfermera titulada en Israel?', ['A practical nurse with 5 years of experience', 'A final-year nursing student working alone', 'Any nurse with a valid licence from abroad', 'Only an RN licensed by the Ministry of Health'], ['Una auxiliar de enfermería con 5 años de experiencia', 'Una estudiante de último año trabajando sola', 'Cualquier enfermera con licencia extranjera vigente', 'Solo una RN con licencia del Ministerio de Salud'], 'Only nurses registered by the Ministry of Health may practise as RNs. A foreign licence does not qualify on its own: that is why nurses trained abroad take the licensure exam.', 'Solo las enfermeras registradas por el Ministerio de Salud pueden ejercer como RN. Una licencia extranjera no basta por sí sola: por eso las enfermeras formadas fuera hacen el examen de licencia.'],
    [3, 2, 'You are asked to perform a procedure you have never been trained or authorized to do. Best action?', 'Te piden realizar un procedimiento para el que nunca te formaron ni autorizaron. ¿Mejor acción?', ['Do it carefully, following the manufacturer’s leaflet', 'Do it while the physician guides you by phone', 'Decline, tell the charge nurse, ask for training', 'Do it after explaining your inexperience to the patient'], ['Hacerlo con cuidado siguiendo el prospecto del fabricante', 'Hacerlo mientras el médico te guía por teléfono', 'Negarte, avisar a la responsable y pedir formación', 'Hacerlo tras explicar tu inexperiencia al paciente'], 'A nurse acts only within her authorization and competence. Declining and escalating keeps the patient safe. Patient consent or remote guidance does not make an untrained procedure safe or legal.', 'La enfermera actúa solo dentro de su autorización y competencia. Negarse y escalar protege al paciente. El consentimiento del paciente o la guía a distancia no hacen seguro ni legal un procedimiento sin formación.']
  ]
});
